// === Fleet Manifest Loader with Validation ===
// Expects msg.payload to be JSON string from File In node

try {
    const raw = (typeof msg.payload === "string") ? JSON.parse(msg.payload) : msg.payload;
    if (!raw || typeof raw !== "object") throw new Error("Manifest is not an object");
    if (!raw.devices || typeof raw.devices !== "object") throw new Error("Manifest missing devices");

    // Normalize device keys to uppercase 12-hex (strip separators)
    const normDevices = {};
    for (const [k, v] of Object.entries(raw.devices)) {
        const nk = String(k).toUpperCase().replace(/[^0-9A-F]/g, "");
        if (!/^[0-9A-F]{12}$/.test(nk)) {
            node.warn(`Skipping invalid MAC key: ${k}`);
            continue;
        }
        normDevices[nk] = v;
    }

    const manifest = { ...raw, devices: normDevices };

    global.set("fleet_manifest", manifest);
    flow.set("manifest", manifest);

    const count = Object.keys(manifest.devices).length;
    node.log(`Loaded manifest fleet_id=${manifest.fleet_id}, devices=${count}`);
    msg.payload = manifest;
    return msg;
} catch (e) {
    node.error(`Failed to load manifest: ${e.message}`, msg);
    return null;
}

// === Bootstrap Config Router ===
// Expected incoming topic format: bootstrap/announce/{deviceID}

// Build Config from Manifest (replace function body)
const parts = String(msg.topic || "").split("/");
if (parts.length < 3) return null;

const rawId = parts[2];
const normId = String(rawId).toUpperCase().replace(/[^A-F0-9]/g, "");

const manifest = global.get("fleet_manifest");
if (!manifest || !manifest.devices) {
  node.warn("Manifest not loaded in global context");
  return null;
}

// normalized lookup
const byId = {};
for (const [k, v] of Object.entries(manifest.devices)) {
  const keyNorm = String(k).toUpperCase().replace(/[^A-F0-9]/g, "");
  if (keyNorm) byId[keyNorm] = v;

  if (v && v.device_id) {
    const idNorm = String(v.device_id).toUpperCase().replace(/[^A-F0-9]/g, "");
    if (idNorm) byId[idNorm] = v;
  }
  if (v && v.mac) {
    const macNorm = String(v.mac).toUpperCase().replace(/[^A-F0-9]/g, "");
    if (macNorm) byId[macNorm] = v;
  }
}

const entry = byId[normId];
if (!entry) {
  node.warn(`Unknown device: ${rawId} (norm=${normId})`);
  return null;
}

const st = msg.payload?.status;
if (st === "bootstrapped") return null;

return {
  topic: `bootstrap/config/${normId}`,
  payload: {
    fleet_id: manifest.fleet_id,
    name: entry.name,
    ...(entry.vessel_id ? { vessel_id: entry.vessel_id } : {}),
    ...(entry.ha ? { ha: entry.ha } : {})
  }
};

// === Fleet Table Bootstrap Updater ===
// Handles bootstrap/announce/{MAC} - enriches with manifest data

const parts = String(msg.topic || "").split("/");
if (parts.length < 3) return null;

const rawMac = parts[2];
const normMac = String(rawMac).toUpperCase().replace(/[^A-F0-9]/g, "");

const p = msg.payload || {};
const status = p.status || "pending";

const manifest = global.get("fleet_manifest") || {};
const devices = manifest.devices || {};

// Build normalized manifest index (supports keys with/without separators)
const byMac = {};
for (const [k, v] of Object.entries(devices)) {
  const keyNorm = String(k).toUpperCase().replace(/[^A-F0-9]/g, "");
  if (keyNorm) byMac[keyNorm] = v;

  if (v && v.device_id) {
    const idNorm = String(v.device_id).toUpperCase().replace(/[^A-F0-9]/g, "");
    if (idNorm) byMac[idNorm] = v;
  }
  if (v && v.mac) {
    const macNorm = String(v.mac).toUpperCase().replace(/[^A-F0-9]/g, "");
    if (macNorm) byMac[macNorm] = v;
  }
}

const deviceInfo = byMac[normMac] || null;

// Update fleet table
let table = flow.get("fleet_table") || [];
let idx = table.findIndex(e => String(e.device_id || "").toUpperCase().replace(/[^A-F0-9]/g, "") === normMac);

const row = {
  device_id: normMac,
  name: deviceInfo?.name || "",
  fleet_id: manifest.fleet_id || "",
  vessel_id: deviceInfo?.vessel_id || "",
  status,
  uptime: 0,
  last_seen: new Date().toLocaleString()
};

if (idx >= 0) {
  table[idx] = { ...table[idx], ...row };
} else {
  table.push(row);
}

flow.set("fleet_table", table);

// pass vessel context downstream for resolver
if (deviceInfo?.vessel_id) {
  msg.vessel_id = deviceInfo.vessel_id;
  msg.device_id = normMac;
  flow.set(`device_vessel::${normMac}`, deviceInfo.vessel_id);
}

msg.payload = table;
return msg;

// === Fleet Table Health/Status Updater ===
// Handles health messages from devices

const parts = (msg.topic || '').split('/');
const p = msg.payload || {};

// Parse topic: fleet/{fleet_id}/vessels/{vessel_id}/devices/{MAC}/health
if (parts.length < 6 || parts[0] !== 'fleet' || parts[2] !== 'vessels' || parts[4] !== 'devices' || parts[6] !== 'health') {
    return null; // Wrong topic format
}

const fleet_id = parts[1];
const vessel_id = parts[3];
const mac = parts[5];

// Validate MAC format (12 hex characters)
if (!mac || !/^[0-9A-F]{12}$/i.test(mac)) {
    node.warn(`Invalid MAC address: ${mac}`);
    return null;
}

let table = flow.get('fleet_table') || [];
let idx = table.findIndex(e => e.device_id === mac);

if (idx >= 0) {
    // Update health metrics for existing device only
    if (p.uptime !== undefined) table[idx].uptime = p.uptime;
    table[idx].last_seen = new Date().toLocaleString();
} else {
    // Don't create new entries from health messages - wait for bootstrap
    node.warn(`Health message from unknown device ${mac} - ignoring until bootstrapped`);
    return null;
}

flow.set('fleet_table', table);
return { payload: table };

// --- Bridge Filter ---
// Pass only CRSF messages from manifest devices with role "bridge".
// Adds fleet + source metadata for downstream routing.

const parts = (msg.topic || "").split("/");
if (parts.length < 5) return null;

const fleet_id = parts[1];
const device_id = (parts[3] || "").toUpperCase();

const manifest = global.get("fleet_manifest");
if (!manifest || !manifest.devices) return null;

// Build uppercase map once per message for case-insensitive lookup
const norm = {};
for (const [k, v] of Object.entries(manifest.devices)) {
  norm[k.toUpperCase()] = v;
}

const entry = norm[device_id];
if (!entry) return null; // IMPORTANT: avoid undefined.role crash

const roles = Array.isArray(entry.role) ? entry.role : [entry.role];
const roleNorm = roles.map(r => String(r || "").trim().toLowerCase());
if (!roleNorm.includes("bridge")) return null;

msg.meta = {
  fleet_id,
  source_device_id: device_id,
  source_name: entry.name || device_id
};

return msg;

// === Fleet Router ===
// CH10 <= 0 => ROV-02
// CH10 > 0  => TENDER-01
// output[0] = ROV path, output[1] = Tender path
const ch = msg.payload || {};
const manifest = global.get("fleet_manifest") || {};
const fleet_id = msg.meta?.fleet_id || manifest.fleet_id || "";

const targetKind = Number(ch.ch10 || 0) > 0 ? "tender" : "rov";
const vessel_id = (targetKind === "tender") ? "tender-01" : "rov-02";

// Latch previous vessel on switch-away
const prevActive = flow.get("active_vessel_id");
if (prevActive && prevActive !== vessel_id) {
  const prevSnap = flow.get(`veh_last::${prevActive}`);
  if (prevSnap && Array.isArray(prevSnap.thr)) {
    flow.set(`veh_latched::${prevActive}`, true);
  }
}

// Active vessel is always live-controlled
flow.set(`veh_latched::${vessel_id}`, false);
flow.set("active_vessel_id", vessel_id);

const roles = ["driver"];
const rad2deg = 180 / Math.PI;

const heading_rad = Number(flow.get(`nav::${vessel_id}::heading`) || 0);
const pitch_rad   = Number(flow.get(`nav::${vessel_id}::pitch`) || 0);
const roll_rad    = Number(flow.get(`nav::${vessel_id}::roll`) || 0);
const yaw_rate_rs = Number(flow.get(`nav::${vessel_id}::yaw_rate`) || 0);
const hdop = Number(flow.get(`nav::${vessel_id}::hdop`));

msg.payload = Object.assign({}, ch, {
  heading: heading_rad * rad2deg,
  pitch: pitch_rad * rad2deg,
  roll: roll_rad * rad2deg,

  lat: Number(flow.get(`nav::${vessel_id}::lat`) || 0),
  lon: Number(flow.get(`nav::${vessel_id}::lon`) || 0),
  alt: Number(flow.get(`nav::${vessel_id}::alt`) || 0),
  depth: Number(flow.get(`nav::${vessel_id}::depth`) || 0),

  // new nav standard only gives yaw rate for now
  pitch_rate: 0,
  roll_rate: 0,
  yaw_rate: yaw_rate_rs * rad2deg,

  sog: Number(flow.get(`nav::${vessel_id}::sog`) || 0),
  speed: Number(flow.get(`nav::${vessel_id}::speed`) || 0),
  sats: Number(flow.get(`nav::${vessel_id}::sats`) || 0),
  hdop: Number.isFinite(hdop) ? hdop : undefined,
  cog: Number(flow.get(`nav::${vessel_id}::cog`) || 0) * rad2deg
});

msg.router = { fleet_id, vessel_id, kind: targetKind, roles };

// Heartbeat source cache
flow.set("last_channels", msg.payload);
flow.set("last_router", msg.router);
flow.set("last_router_ts", Date.now());

if (vessel_id === "rov-02") {
  flow.set("last_rov_channels", msg.payload);
}

return targetKind === "rov" ? [msg, null] : [null, msg];

// ═══════════════════════════════════════════════════════════════════════════
// ROV FLIGHT MODE CONTROLLER - MANUAL / STABLE / MAG (GPS POSITION HOLD)
// ═══════════════════════════════════════════════════════════════════════════
//
// FLIGHT MODES:
// -------------
// MANUAL: Direct translational/yaw passthrough, but roll/pitch are angle-held
// - Raw pilot authority on surge/sway/heave/yaw via downstream mixer inputs
// - Roll/pitch pots define target attitude
// - IMU + gyro provide PD stabilization around those target angles
//
// STABLE: Attitude/heading/depth hold with world-frame stick input
// - Holds roll, pitch, yaw (heading), and depth at target setpoints
// - Stick inputs transformed from world-frame to body-frame so that
//   "forward" stays forward relative to the water surface regardless
//   of current roll/pitch angle
// - Pilot trims targets by moving sticks (setpoints follow stick input)
// - PID control: P + I + D with gyro rate damping
//
// MAG: GPS position hold + attitude/depth hold
// - Same world-frame stick transform as STABLE
// - Additionally holds GPS lat/lon position
// - Forces level flight (roll=0, pitch=0) for stable GPS tracking
// - GPS errors converted to body-frame tilt commands
// - Future: waypoint following / autonomous nav
//
// WORLD-TO-BODY STICK TRANSFORM (STABLE + MAG):
// -----------------------------------------------
// Pilot stick intent is in world-frame (relative to water surface).
// The transform rotates surge/sway/heave through current roll and pitch
// so the ROV moves as the pilot expects regardless of its attitude.
//
// body_surge = heave_w·sin(p) + surge_w·cos(p)
// body_sway  = heave_w·sin(r)·cos(p) + sway_w·cos(r)
// body_heave = heave_w·cos(p)·cos(r) - sway_w·sin(r) - surge_w·sin(p)
//
// Rotational axes (roll/pitch/yaw corrections from PID) are already in
// body-frame and are NOT transformed.
//
// CONTROL THEORY:
// ---------------
// PID: Output = P×error + I×∫error·dt + D×dError/dt
// P: immediate response, can oscillate without damping
// I: eliminates steady-state error (buoyancy, current, drift)
// D: damping via gyro rates, prevents overshoot
//
// TUNING GUIDE:
// -------------
// 1. DEPTH HOLD: P=0.3, I=0.05
// 2. HEADING HOLD: P=0.2, I=0.02, D=0.06
// 3. ROLL STAB: P=0.3, D=0.2
// 4. PITCH STAB: P=0.3, D=0.2
// 5. GPS HOLD: P=0.15, deadzone=1.0m, max_tilt=0.3
//
// DESIGN NOTES:
// -------------
// • HA helpers are synced into flow context under tuning::rov::*
// • This node reads them every cycle
// • If a helper is missing / bad / unavailable, a safe default is used
// • Bad tuning values are ignored here; they do NOT overwrite control logic
//
// ═══════════════════════════════════════════════════════════
// DEFAULT TUNING VALUES
// ═══════════════════════════════════════════════════════════
//
// These are the fallback values used if no HA helper has been received yet.
// Keep these sane: they are the "safe boot" behaviour.
//

const DEFAULTS = {
    deadband: 5,

    heading_trim_rate: 0.3,
    roll_trim_rate: 0.3,
    pitch_trim_rate: 0.3,
    depth_trim_rate: 0.05,

    heading_P: 0.2,
    roll_P: 0.3,
    pitch_P: 0.3,
    depth_P: 0.3,

    depth_I: 0.05,
    heading_I: 0.02,

    roll_D: 0.2,
    pitch_D: 0.2,
    yaw_D: 0.06,

    depth_I_max: 0.3,
    heading_I_max: 0.2,

    correction_exponent: 1.3,

    gps_P: 0.15,
    gps_max_tilt: 0.3,
    gps_deadzone: 1.0,
    gps_jump_threshold: 10,
    gps_slew_rate: 0.05,

    meters_per_deg_lat: 111000,
    meters_per_deg_lon: 88000,

    roll_slew: 0.1,
    pitch_slew: 0.1,
    yaw_slew: 0.1,
    heave_slew: 0.1,

    gyro_filter_alpha: 0.3,
    max_sensor_age: 2000,

    manual_roll_P: 0.05,
    manual_roll_D: 0.00,
    manual_pitch_P: 0.05,
    manual_pitch_D: 0.00,
    manual_angle_max_deg: 60,

    axis_clamp_roll: 0.35,
    axis_clamp_pitch: 0.35,
    axis_clamp_yaw: 0.30,
    axis_clamp_heave: 1.00
};

// ═══════════════════════════════════════════════════════════
// UTILITY FUNCTIONS
// ═══════════════════════════════════════════════════════════

function clamp(v, min = -1, max = 1) {
    return Math.max(min, Math.min(max, v));
}

function applyDeadband(value, deadband) {
    return Math.abs(value) < deadband ? 0 : value;
}

function nonlinearCorrection(error, baseGain, exponent = 1.3) {
    const sign = Math.sign(error);
    const magnitude = Math.abs(error);
    return sign * baseGain * Math.pow(magnitude, exponent);
}

function slewLimit(current, target, maxDelta) {
    const delta = target - current;
    if (Math.abs(delta) <= maxDelta) return target;
    return current + Math.sign(delta) * maxDelta;
}

// Wrap heading error into -180..+180 degrees.
function wrapHeadingError(errDeg) {
    return (((errDeg + 180) % 360) + 360) % 360 - 180;
}

// Rotate world-frame stick inputs into body-frame using current roll/pitch.
// Inputs are in percent [-100, 100], output is also in percent [-100, 100].
// roll_deg and pitch_deg come from the IMU (ch.roll, ch.pitch).
function worldToBody(surge_w, sway_w, heave_w, roll_deg, pitch_deg) {
    const r = roll_deg * Math.PI / 180;
    const p = pitch_deg * Math.PI / 180;

    return {
        surge: heave_w * Math.sin(p) + surge_w * Math.cos(p),
        sway: heave_w * Math.sin(r) * Math.cos(p) + sway_w * Math.cos(r),
        heave: heave_w * Math.cos(p) * Math.cos(r) - sway_w * Math.sin(r) - surge_w * Math.sin(p)
    };
}

// Safe numeric getter from flow context.
// Returns fallback if:
// - key missing
// - null/undefined
// - NaN / non-number
function getNum(path, fallback) {
    const raw = flow.get(path);
    const n = Number(raw);
    return Number.isFinite(n) ? n : fallback;
}

// Resolve all live tuning from flow context.
// This keeps HA / Node-RED decoupled:
// HA = UI / source of truth
// flow context = live working state
// mixer = consumer with safe defaults
function buildParams() {
    return {
        deadband: getNum("tuning::rov::input_deadband", DEFAULTS.deadband),

        heading_trim_rate: DEFAULTS.heading_trim_rate,
        roll_trim_rate: DEFAULTS.roll_trim_rate,
        pitch_trim_rate: DEFAULTS.pitch_trim_rate,
        depth_trim_rate: DEFAULTS.depth_trim_rate,

        heading_P: getNum("tuning::rov::heading_p", DEFAULTS.heading_P),
        roll_P: getNum("tuning::rov::roll_p", DEFAULTS.roll_P),
        pitch_P: getNum("tuning::rov::pitch_p", DEFAULTS.pitch_P),
        depth_P: getNum("tuning::rov::depth_p", DEFAULTS.depth_P),

        depth_I: getNum("tuning::rov::depth_i", DEFAULTS.depth_I),
        heading_I: getNum("tuning::rov::heading_i", DEFAULTS.heading_I),

        roll_D: getNum("tuning::rov::roll_d", DEFAULTS.roll_D),
        pitch_D: getNum("tuning::rov::pitch_d", DEFAULTS.pitch_D),
        yaw_D: getNum("tuning::rov::yaw_d", DEFAULTS.yaw_D),

        depth_I_max: DEFAULTS.depth_I_max,
        heading_I_max: DEFAULTS.heading_I_max,

        correction_exponent: DEFAULTS.correction_exponent,

        gps_P: getNum("tuning::rov::gps_p", DEFAULTS.gps_P),
        gps_max_tilt: getNum("tuning::rov::gps_max_tilt", DEFAULTS.gps_max_tilt),
        gps_deadzone: getNum("tuning::rov::gps_deadzone", DEFAULTS.gps_deadzone),
        gps_jump_threshold: getNum("tuning::rov::gps_jump_threshold", DEFAULTS.gps_jump_threshold),
        gps_slew_rate: getNum("tuning::rov::gps_slew_rate", DEFAULTS.gps_slew_rate),

        meters_per_deg_lat: DEFAULTS.meters_per_deg_lat,
        meters_per_deg_lon: DEFAULTS.meters_per_deg_lon,

        roll_slew: getNum("tuning::rov::roll_slew", DEFAULTS.roll_slew),
        pitch_slew: getNum("tuning::rov::pitch_slew", DEFAULTS.pitch_slew),
        yaw_slew: getNum("tuning::rov::yaw_slew", DEFAULTS.yaw_slew),
        heave_slew: getNum("tuning::rov::heave_slew", DEFAULTS.heave_slew),

        gyro_filter_alpha: getNum("tuning::rov::gyro_filter_alpha", DEFAULTS.gyro_filter_alpha),
        max_sensor_age: DEFAULTS.max_sensor_age,

        manual_roll_P: getNum("tuning::rov::manual_roll_p", DEFAULTS.manual_roll_P),
        manual_roll_D: getNum("tuning::rov::manual_roll_d", DEFAULTS.manual_roll_D),
        manual_pitch_P: getNum("tuning::rov::manual_pitch_p", DEFAULTS.manual_pitch_P),
        manual_pitch_D: getNum("tuning::rov::manual_pitch_d", DEFAULTS.manual_pitch_D),
        manual_angle_max_deg: getNum("tuning::rov::manual_angle_max_deg", DEFAULTS.manual_angle_max_deg),

        axis_clamp_roll: getNum("tuning::rov::axis_clamp_roll", DEFAULTS.axis_clamp_roll),
        axis_clamp_pitch: getNum("tuning::rov::axis_clamp_pitch", DEFAULTS.axis_clamp_pitch),
        axis_clamp_yaw: getNum("tuning::rov::axis_clamp_yaw", DEFAULTS.axis_clamp_yaw),
        axis_clamp_heave: getNum("tuning::rov::axis_clamp_heave", DEFAULTS.axis_clamp_heave)
    };
}

// Live params for this cycle.
// Built once per message so the whole control pass uses a consistent snapshot.
const PARAMS = buildParams();

// ═══════════════════════════════════════════════════════════
// EXTRACT INPUT DATA
// ═══════════════════════════════════════════════════════════

const ch = msg.payload || {};
const vessel_id = msg.router?.vessel_id || "rov-unknown";

// ═══════════════════════════════════════════════════════════
// PERSISTENT STATE - CONTEXT KEYS
// ═══════════════════════════════════════════════════════════
//
// These are per-vessel so multiple craft can share the same function safely.
//

const keyLast = `rov:lastMode:${vessel_id}`;
const keyHead = `rov:targetHeading:${vessel_id}`;
const keyRoll = `rov:targetRoll:${vessel_id}`;
const keyPitch = `rov:targetPitch:${vessel_id}`;
const keyLat = `rov:targetLat:${vessel_id}`;
const keyLon = `rov:targetLon:${vessel_id}`;
const keyDepth = `rov:targetDepth:${vessel_id}`;

const keyDepthI = `rov:depthIntegral:${vessel_id}`;
const keyHeadingI = `rov:headingIntegral:${vessel_id}`;

const keyPrevRoll = `rov:prevRollCorr:${vessel_id}`;
const keyPrevPitch = `rov:prevPitchCorr:${vessel_id}`;
const keyPrevYaw = `rov:prevYawCorr:${vessel_id}`;
const keyPrevHeave = `rov:prevHeaveCorr:${vessel_id}`;

const keyPrevGPSRoll = `rov:prevGPSRollCorr:${vessel_id}`;
const keyPrevGPSPitch = `rov:prevGPSPitchCorr:${vessel_id}`;

const keyPrevNorth = `rov:prevNorthErr:${vessel_id}`;
const keyPrevEast = `rov:prevEastErr:${vessel_id}`;

const keyFilteredRollRate = `rov:filteredRollRate:${vessel_id}`;
const keyFilteredPitchRate = `rov:filteredPitchRate:${vessel_id}`;
const keyFilteredYawRate = `rov:filteredYawRate:${vessel_id}`;

const keyLastGyroTime = `rov:lastGyroTime:${vessel_id}`;
const keyLastDepthTime = `rov:lastDepthTime:${vessel_id}`;
const keyLastGPSTime = `rov:lastGPSTime:${vessel_id}`;

// ═══════════════════════════════════════════════════════════
// RESTORE PERSISTENT STATE
// ═══════════════════════════════════════════════════════════

let lastMode = context.get(keyLast);

let targetHeading = context.get(keyHead);
let targetRoll = context.get(keyRoll);
let targetPitch = context.get(keyPitch);

let targetLat = context.get(keyLat);
let targetLon = context.get(keyLon);
let targetDepth = context.get(keyDepth);

let depthIntegral = context.get(keyDepthI) || 0;
let headingIntegral = context.get(keyHeadingI) || 0;

let prevRollCorr = context.get(keyPrevRoll) || 0;
let prevPitchCorr = context.get(keyPrevPitch) || 0;
let prevYawCorr = context.get(keyPrevYaw) || 0;
let prevHeaveCorr = context.get(keyPrevHeave) || 0;

let prevGPSRollCorr = context.get(keyPrevGPSRoll) || 0;
let prevGPSPitchCorr = context.get(keyPrevGPSPitch) || 0;

let filteredRollRate = context.get(keyFilteredRollRate) || 0;
let filteredPitchRate = context.get(keyFilteredPitchRate) || 0;
let filteredYawRate = context.get(keyFilteredYawRate) || 0;

// ═══════════════════════════════════════════════════════════
// SENSOR STALENESS CHECK
// ═══════════════════════════════════════════════════════════
//
// Rather than instantly trusting the latest values forever,
// we timestamp the last good arrival of each sensor family.
// If data is stale, the relevant controller gracefully degrades.
//

const nowMs = Date.now();

let lastGyroTime = context.get(keyLastGyroTime);
let lastDepthTime = context.get(keyLastDepthTime);
let lastGPSTime = context.get(keyLastGPSTime);

if (
    typeof ch.roll_rate === "number" &&
    typeof ch.pitch_rate === "number" &&
    typeof ch.yaw_rate === "number"
) {
    lastGyroTime = nowMs;
    context.set(keyLastGyroTime, nowMs);
}

if (typeof ch.depth === "number") {
    lastDepthTime = nowMs;
    context.set(keyLastDepthTime, nowMs);
}

if (typeof ch.lat === "number" && typeof ch.lon === "number") {
    lastGPSTime = nowMs;
    context.set(keyLastGPSTime, nowMs);
}

const gyroStale =
    typeof lastGyroTime !== "number" ||
    nowMs - lastGyroTime > PARAMS.max_sensor_age;

const depthStale =
    typeof lastDepthTime !== "number" ||
    nowMs - lastDepthTime > PARAMS.max_sensor_age;

const gpsStale =
    typeof lastGPSTime !== "number" ||
    nowMs - lastGPSTime > PARAMS.max_sensor_age;

// ═══════════════════════════════════════════════════════════
// MODE DETECTION AND TRANSITIONS
// ═══════════════════════════════════════════════════════════

const mode = ch.flight_mode || "MANUAL";

function resetAllTargets() {
    targetHeading = null;
    targetRoll = null;
    targetPitch = null;
    targetLat = null;
    targetLon = null;
    targetDepth = null;

    depthIntegral = 0;
    headingIntegral = 0;

    prevRollCorr = 0;
    prevPitchCorr = 0;
    prevYawCorr = 0;
    prevHeaveCorr = 0;
    prevGPSRollCorr = 0;
    prevGPSPitchCorr = 0;

    context.set(keyHead, null);
    context.set(keyRoll, null);
    context.set(keyPitch, null);
    context.set(keyLat, null);
    context.set(keyLon, null);
    context.set(keyDepth, null);

    context.set(keyDepthI, 0);
    context.set(keyHeadingI, 0);

    context.set(keyPrevRoll, 0);
    context.set(keyPrevPitch, 0);
    context.set(keyPrevYaw, 0);
    context.set(keyPrevHeave, 0);
    context.set(keyPrevGPSRoll, 0);
    context.set(keyPrevGPSPitch, 0);

    context.set(keyPrevNorth, null);
    context.set(keyPrevEast, null);
}

if (mode === "STABLE" && lastMode !== "STABLE") {
    targetHeading = typeof ch.heading === "number" ? ch.heading : targetHeading;
    targetRoll = typeof ch.roll === "number" ? ch.roll : targetRoll;
    targetPitch = typeof ch.pitch === "number" ? ch.pitch : targetPitch;
    targetDepth = typeof ch.depth === "number" ? ch.depth : 1.0;

    depthIntegral = 0;
    headingIntegral = 0;

    prevRollCorr = 0;
    prevPitchCorr = 0;
    prevYawCorr = 0;
    prevHeaveCorr = 0;

    context.set(keyHead, targetHeading);
    context.set(keyRoll, targetRoll);
    context.set(keyPitch, targetPitch);
    context.set(keyDepth, targetDepth);

    context.set(keyDepthI, 0);
    context.set(keyHeadingI, 0);

    context.set(keyPrevRoll, 0);
    context.set(keyPrevPitch, 0);
    context.set(keyPrevYaw, 0);
    context.set(keyPrevHeave, 0);
}

if (mode === "MAG" && lastMode !== "MAG") {
    targetLat = typeof ch.lat === "number" ? ch.lat : targetLat;
    targetLon = typeof ch.lon === "number" ? ch.lon : targetLon;
    targetHeading = typeof ch.heading === "number" ? ch.heading : targetHeading;

    // In MAG mode, level attitude is the baseline.
    targetRoll = 0;
    targetPitch = 0;
    targetDepth = typeof ch.depth === "number" ? ch.depth : 1.0;

    depthIntegral = 0;
    headingIntegral = 0;

    prevRollCorr = 0;
    prevPitchCorr = 0;
    prevYawCorr = 0;
    prevHeaveCorr = 0;
    prevGPSRollCorr = 0;
    prevGPSPitchCorr = 0;

    context.set(keyLat, targetLat);
    context.set(keyLon, targetLon);
    context.set(keyHead, targetHeading);
    context.set(keyRoll, targetRoll);
    context.set(keyPitch, targetPitch);
    context.set(keyDepth, targetDepth);

    context.set(keyDepthI, 0);
    context.set(keyHeadingI, 0);

    context.set(keyPrevRoll, 0);
    context.set(keyPrevPitch, 0);
    context.set(keyPrevYaw, 0);
    context.set(keyPrevHeave, 0);
    context.set(keyPrevGPSRoll, 0);
    context.set(keyPrevGPSPitch, 0);

    context.set(keyPrevNorth, null);
    context.set(keyPrevEast, null);
}

if (mode === "MANUAL") {
    resetAllTargets();
}

context.set(keyLast, mode);

// ═══════════════════════════════════════════════════════════
// FILTER GYRO RATES (for D-term)
// ═══════════════════════════════════════════════════════════
//
// Low-pass filter raw gyro to reduce noisy D-term behaviour.
//

if (!gyroStale) {
    const alpha = clamp(PARAMS.gyro_filter_alpha, 0, 1);

    filteredRollRate =
        alpha * (ch.roll_rate || 0) + (1 - alpha) * filteredRollRate;
    filteredPitchRate =
        alpha * (ch.pitch_rate || 0) + (1 - alpha) * filteredPitchRate;
    filteredYawRate =
        alpha * (ch.yaw_rate || 0) + (1 - alpha) * filteredYawRate;

    context.set(keyFilteredRollRate, filteredRollRate);
    context.set(keyFilteredPitchRate, filteredPitchRate);
    context.set(keyFilteredYawRate, filteredYawRate);
}
// ═══════════════════════════════════════════════════════════
// FLIGHT CONTROL OUTPUTS
// ═══════════════════════════════════════════════════════════

let roll_thrust = 0;
let pitch_thrust = 0;
let yaw_thrust = 0;
let heave_thrust = 0;

// ───────────────────────────────────────────────────────────
// MANUAL MODE
// ───────────────────────────────────────────────────────────
//
// Pure passthrough. No attitude hold.
// All axes are direct pilot control.
//

if (mode === "MANUAL") {
    headingIntegral = 0;
    depthIntegral = 0;
    context.set(keyHeadingI, 0);
    context.set(keyDepthI, 0);

    context.set(keyPrevRoll, 0);
    context.set(keyPrevPitch, 0);
    context.set(keyPrevYaw, 0);
    context.set(keyPrevHeave, 0);
    context.set(keyPrevGPSPitch, 0);
    context.set(keyPrevGPSRoll, 0);
    context.set(`mag_active::${vessel_id}`, false);

    roll_thrust = clamp((applyDeadband(ch.ch6 || 0, PARAMS.deadband) / 100) * 0.5, -1, 1);
    pitch_thrust = clamp((applyDeadband(ch.ch7 || 0, PARAMS.deadband) / 100) * 0.5, -1, 1);
    yaw_thrust = -clamp((applyDeadband(ch.ch4 || 0, PARAMS.deadband) / 100) * 0.4, -1, 1);
    heave_thrust = clamp((applyDeadband(ch.ch3 || 0, PARAMS.deadband) / 100) * 0.7, -1, 1);
}

// ───────────────────────────────────────────────────────────
// STABLE MODE
// ───────────────────────────────────────────────────────────
//
// Roll + pitch hold via PD control.
// Pots (CH6/CH7) set target angle: 0 = level, ±100 = ±max_angle.
// Yaw and heave are pure pilot passthrough.
// Translational pilot input is world-frame transformed.
//

else if (mode === "STABLE") {
    //node.warn(`STABLE entry: roll=${ch.roll} pitch=${ch.pitch} heading=${ch.heading} depth=${ch.depth} rollRate=${filteredRollRate} pitchRate=${filteredPitchRate} yawRate=${filteredYawRate} ch6=${ch.ch6} ch7=${ch.ch7} ch4=${ch.ch4} ch3=${ch.ch3} targetRoll=${targetRoll} targetPitch=${targetPitch}`);

    const roll_stick  = applyDeadband(ch.ch6 || 0, PARAMS.deadband);
    const pitch_stick = applyDeadband(ch.ch7 || 0, PARAMS.deadband);
    const yaw_stick   = -applyDeadband(ch.ch4 || 0, PARAMS.deadband);

    const surge_w = applyDeadband(ch.ch2 || 0, PARAMS.deadband);
    const sway_w  = applyDeadband(ch.ch1 || 0, PARAMS.deadband);
    const heave_w = applyDeadband(ch.ch3 || 0, PARAMS.deadband);

    const body = worldToBody(
        surge_w, sway_w, heave_w,
        ch.roll || 0, ch.pitch || 0
    );

    ch.ch1 = body.sway;
    ch.ch2 = body.surge;
    ch.ch3 = body.heave;

    // Pot sets target angle: 0 stick = level, ±100 = ±max_angle
    targetRoll = (roll_stick / 100) * PARAMS.manual_angle_max_deg;
    targetPitch = (pitch_stick / 100) * PARAMS.manual_angle_max_deg;

    context.set(keyRoll, targetRoll);
    context.set(keyPitch, targetPitch);
    context.set(`mag_active::${vessel_id}`, false);

    // Not holding heading/depth in STABLE
    headingIntegral = 0;
    depthIntegral = 0;
    context.set(keyHeadingI, 0);
    context.set(keyDepthI, 0);
    context.set(keyPrevYaw, 0);
    context.set(keyPrevHeave, 0);

    // Clear heading/depth targets so MAG transition always captures fresh
    targetHeading = null;
    targetDepth = null;
    context.set(keyHead, null);
    context.set(keyDepth, null);

    // Errors
    const roll_err = targetRoll - (ch.roll || 0);
    const pitch_err = targetPitch - (ch.pitch || 0);

    // PD control
    let rollCorr = slewLimit(
        prevRollCorr,
        nonlinearCorrection(roll_err, PARAMS.roll_P, PARAMS.correction_exponent) +
        (gyroStale ? 0 : -filteredRollRate * PARAMS.roll_D),
        PARAMS.roll_slew
    );

    let pitchCorr = slewLimit(
        prevPitchCorr,
        nonlinearCorrection(pitch_err, PARAMS.pitch_P, PARAMS.correction_exponent) +
        (gyroStale ? 0 : -filteredPitchRate * PARAMS.pitch_D),
        PARAMS.pitch_slew
    );

    context.set(keyPrevRoll, rollCorr);
    context.set(keyPrevPitch, pitchCorr);

    roll_thrust = clamp(rollCorr, -PARAMS.axis_clamp_roll, PARAMS.axis_clamp_roll);
    pitch_thrust = clamp(pitchCorr, -PARAMS.axis_clamp_pitch, PARAMS.axis_clamp_pitch);

    // Yaw + heave passthrough
    yaw_thrust = clamp(yaw_stick / 100, -PARAMS.axis_clamp_yaw, PARAMS.axis_clamp_yaw);

    heave_thrust = clamp(body.heave / 100, -PARAMS.axis_clamp_heave, PARAMS.axis_clamp_heave);
}

// ───────────────────────────────────────────────────────────
// MAG MODE
// ───────────────────────────────────────────────────────────
//
// Holds pitch + roll + heading + depth.
// On entry, captures current heading and depth as targets.
// If targets are null (from STABLE) or stale (from previous
// deploy), recaptures from live sensors.
// GPS position-hold tilt logic commented out for later reuse.
//    node.warn(`MAG entry: roll=${ch.roll} pitch=${ch.pitch} heading=${ch.heading} depth=${ch.depth} rollRate=${filteredRollRate} pitchRate=${filteredPitchRate} yawRate=${filteredYawRate} ch6=${ch.ch6} ch7=${ch.ch7} ch4=${ch.ch4} ch3=${ch.ch3} targetRoll=${targetRoll} targetPitch=${targetPitch} targetHeading=${targetHeading} targetDepth=${targetDepth} headingI=${headingIntegral} depthI=${depthIntegral}`);


else if (mode === "MAG") {
    if (!context.get(`mag_active::${vessel_id}`)) {
        targetHeading = typeof ch.heading === "number" ? ch.heading : 0;
        headingIntegral = 0;
        prevYawCorr = 0;
        prevRollCorr = 0;
        prevPitchCorr = 0;
        context.set(keyHead, targetHeading);
        context.set(keyHeadingI, 0);
        context.set(keyPrevYaw, 0);
        context.set(keyPrevRoll, 0);
        context.set(keyPrevPitch, 0);
        context.set(`mag_active::${vessel_id}`, true);

    //    node.warn(`MAG CAPTURED: heading=${targetHeading} ch.heading=${ch.heading}`);
    }

    const roll_stick  = applyDeadband(ch.ch6 || 0, PARAMS.deadband);
    const pitch_stick = applyDeadband(ch.ch7 || 0, PARAMS.deadband);
    const yaw_stick   = applyDeadband(ch.ch4 || 0, PARAMS.deadband);

    const surge_w = applyDeadband(ch.ch2 || 0, PARAMS.deadband);
    const sway_w  = applyDeadband(ch.ch1 || 0, PARAMS.deadband);
    const heave_w = applyDeadband(ch.ch3 || 0, PARAMS.deadband);

    const body = worldToBody(
        surge_w, sway_w, heave_w,
        ch.roll || 0, ch.pitch || 0
    );

    ch.ch1 = body.sway;
    ch.ch2 = body.surge;
    ch.ch3 = body.heave;

    targetRoll = (roll_stick / 100) * PARAMS.manual_angle_max_deg;
    targetPitch = (pitch_stick / 100) * PARAMS.manual_angle_max_deg;
    context.set(keyRoll, targetRoll);
    context.set(keyPitch, targetPitch);

    if (yaw_stick !== 0 && typeof targetHeading === "number") {
        targetHeading += (yaw_stick / 100) * PARAMS.heading_trim_rate;
        targetHeading = ((targetHeading % 360) + 360) % 360;
        context.set(keyHead, targetHeading);
        headingIntegral = 0;
        context.set(keyHeadingI, 0);

    }

    const roll_err = targetRoll - (ch.roll || 0);
    const pitch_err = targetPitch - (ch.pitch || 0);

    let heading_err = 0;
    if (typeof targetHeading === "number" && typeof ch.heading === "number") {
        heading_err = wrapHeadingError(targetHeading - ch.heading);
    }

    if (yaw_stick === 0 && !gyroStale) {
        headingIntegral += heading_err * PARAMS.heading_I;
        headingIntegral = clamp(headingIntegral, -PARAMS.heading_I_max, PARAMS.heading_I_max);
        context.set(keyHeadingI, headingIntegral);
    } else if (gyroStale) {
        headingIntegral = 0;
        context.set(keyHeadingI, 0);
    }

    let rollCorr = slewLimit(
        prevRollCorr,
        nonlinearCorrection(roll_err, PARAMS.roll_P, PARAMS.correction_exponent) +
        (gyroStale ? 0 : -filteredRollRate * PARAMS.roll_D),
        PARAMS.roll_slew
    );

    let pitchCorr = slewLimit(
        prevPitchCorr,
        nonlinearCorrection(pitch_err, PARAMS.pitch_P, PARAMS.correction_exponent) +
        (gyroStale ? 0 : -filteredPitchRate * PARAMS.pitch_D),
        PARAMS.pitch_slew
    );

    let yawCorr = slewLimit(
        prevYawCorr,
        nonlinearCorrection(heading_err, PARAMS.heading_P, PARAMS.correction_exponent) +
        headingIntegral +
        (gyroStale ? 0 : -filteredYawRate * PARAMS.yaw_D),
        PARAMS.yaw_slew
    );
//node.warn(`MAG LOOP: hdg=${ch.heading?.toFixed(1)} tgt=${targetHeading?.toFixed(1)} err=${heading_err?.toFixed(1)} yawRate=${filteredYawRate?.toFixed(1)} yawCorr=${yawCorr?.toFixed(3)} gyroStale=${gyroStale}`);

    context.set(keyPrevRoll, rollCorr);
    context.set(keyPrevPitch, pitchCorr);
    context.set(keyPrevYaw, yawCorr);
    context.set(keyPrevHeave, 0);

    roll_thrust = clamp(rollCorr, -PARAMS.axis_clamp_roll, PARAMS.axis_clamp_roll);
    pitch_thrust = clamp(pitchCorr, -PARAMS.axis_clamp_pitch, PARAMS.axis_clamp_pitch);
    yaw_thrust = clamp(-yawCorr, -PARAMS.axis_clamp_yaw, PARAMS.axis_clamp_yaw);
    heave_thrust = clamp(body.heave / 100, -PARAMS.axis_clamp_heave, PARAMS.axis_clamp_heave);
}

// ═══════════════════════════════════════════════════════════
// OUTPUT
// ═══════════════════════════════════════════════════════════
//
// msg.control is consumed by the downstream thruster mixer.
// We also expose a debug block so you can inspect live tuning
// and controller state without digging through context.
//

msg.control = {
    roll_thrust,
    pitch_thrust,
    yaw_thrust,
    heave_thrust
};

msg.rov_debug = {
    mode,
    vessel_id,
    targets: {
        heading: targetHeading,
        roll: targetRoll,
        pitch: targetPitch,
        lat: targetLat,
        lon: targetLon,
        depth: targetDepth
    },
    stale: {
        gyro: gyroStale,
        depth: depthStale,
        gps: gpsStale
    },
    tuning: {
        deadband: PARAMS.deadband,
        roll_P: PARAMS.roll_P,
        roll_D: PARAMS.roll_D,
        pitch_P: PARAMS.pitch_P,
        pitch_D: PARAMS.pitch_D,
        heading_P: PARAMS.heading_P,
        heading_I: PARAMS.heading_I,
        yaw_D: PARAMS.yaw_D,
        depth_P: PARAMS.depth_P,
        depth_I: PARAMS.depth_I,
        gps_P: PARAMS.gps_P,
        gps_deadzone: PARAMS.gps_deadzone,
        gps_max_tilt: PARAMS.gps_max_tilt
    },
    outputs: {
        roll_thrust,
        pitch_thrust,
        yaw_thrust,
        heave_thrust
    }
};

//msg.debug_tuning = {
//  manual_pitch_p: flow.get("tuning::rov::manual_pitch_p")
//};
return msg;

// ═══════════════════════════════════════════════════════════════════════════
// ROV 8-THRUSTER MIXER WITH LIVE TUNING, PER-THRUSTER DEADBAND,
// REVERSE GAIN COMPENSATION, AND DIRECTION INVERT FLAGS
// ═══════════════════════════════════════════════════════════════════════════
//
// PURPOSE:
// --------
// Converts vehicle control commands into 8 individual thruster outputs.
//
// This mixer combines:
//   • pilot translational stick inputs (surge / sway)
//   • control-loop rotational outputs (roll / pitch / yaw / heave)
//   • per-thruster tuning from flow context
//
// Then it applies, in order:
//   1. first normalization
//   2. reverse gain compensation
//   3. deadband compensation
//   4. per-thruster invert flags
//   5. final normalization
//   6. clamp + arm gate
//
// LIVE TUNING SOURCES:
// --------------------
// Synced from Home Assistant into flow context:
//
//   tuning::rov::input_deadband
//   tuning::rov::thruster_zero_cutoff
//
//   tuning::rov::t1_deadband_fwd ... t8_deadband_fwd
//   tuning::rov::t1_deadband_rev ... t8_deadband_rev
//   tuning::rov::t1_reverse_gain ... t8_reverse_gain
//   tuning::rov::t1_invert       ... t8_invert
//
// If a tuning key is missing or invalid, this mixer falls back to a safe default.
//
// INPUTS:
// -------
// msg.payload:
//   ch1 = sway
//   ch2 = surge
//   ch3 = heave raw stick (used only if control.heave_thrust missing)
//   ch4 = yaw stick
//   ch5 = arm switch
//   ch6 = roll stick/pot
//   ch7 = pitch stick/pot
//
// msg.control:
//   roll_thrust
//   pitch_thrust
//   yaw_thrust
//   heave_thrust
//
// msg.router:
//   fleet_id
//   vessel_id
//
// OUTPUTS:
// --------
// return[0] = MQTT debug / sim output
// return[1] = UDP binary packet
//
// MQTT:
//   topic: fleet/{fleet_id}/vessels/{vessel_id}/thrusters/set
//   payload: { thr: [t1..t8], armed }
//
// UDP:
//   18-byte packet:
//     byte 0   = craft_type
//     byte 1   = craft_id
//     byte 2+  = T1..T8 as int16 little-endian, scaled x10
//
// THRUSTER LAYOUT:
// ----------------
//
// Horizontal thrusters:
//   T1 = front-port
//   T2 = front-starboard
//   T3 = rear-starboard
//   T4 = rear-port
//
// Vertical thrusters:
//   T5 = front-port vertical
//   T6 = front-starboard vertical
//   T7 = rear-starboard vertical
//   T8 = rear-port vertical
//
// SIGN CONVENTIONS:
// -----------------
// +Surge  = forward
// +Sway   = starboard
// +Heave  = up
// +Roll   = starboard down / port up
// +Pitch  = nose down
// +Yaw    = clockwise from above
//
// PURE HEAVE EXPECTATION:
// -----------------------
// +Heave => T5,T6,T7,T8 all positive
// -Heave => T5,T6,T7,T8 all negative
//
// ═══════════════════════════════════════════════════════════════════════════
// Hard kill: block everything immediately.
if (flow.get("safety_kill_active") === true) return null;

// INPUT EXTRACTION
const ch = msg.payload || {};
const c = msg.control || {};
const fleet_id = msg.router?.fleet_id || "";
const vessel_id = msg.router?.vessel_id || flow.get("active_vessel_id");
if (!vessel_id) return null;

const armed = (ch.ch5 || 0) > 0;

// DEFAULTS
const DEFAULTS = {
  input_deadband: 5,
  zero_cutoff: 0.5,
  deadband_fwd: 6,
  deadband_rev: 0,
  reverse_gain: 1.30,
  invert: false
};

// SAFE GETTERS
function getNum(path, fallback) {
  const raw = flow.get(path);
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

function getBool(path, fallback = false) {
  const raw = flow.get(path);
  if (raw === true || raw === false) return raw;
  if (raw === 1 || raw === "1") return true;
  if (raw === 0 || raw === "0") return false;
  const s = String(raw).trim().toLowerCase();
  if (s === "on" || s === "true") return true;
  if (s === "off" || s === "false") return false;
  return fallback;
}

// TUNING SNAPSHOT
const INPUT_DEADBAND = getNum("tuning::rov::input_deadband", DEFAULTS.input_deadband);
const ZERO_CUTOFF = getNum("tuning::rov::thruster_zero_cutoff", DEFAULTS.zero_cutoff);

function buildThrusterTuning(index) {
  return {
    deadband_fwd: getNum(`tuning::rov::t${index}_deadband_fwd`, DEFAULTS.deadband_fwd),
    deadband_rev: getNum(`tuning::rov::t${index}_deadband_rev`, DEFAULTS.deadband_rev),
    reverse_gain: getNum(`tuning::rov::t${index}_reverse_gain`, DEFAULTS.reverse_gain),
    invert: getBool(`tuning::rov::t${index}_invert`, DEFAULTS.invert)
  };
}

const TUNE = {
  t1: buildThrusterTuning(1),
  t2: buildThrusterTuning(2),
  t3: buildThrusterTuning(3),
  t4: buildThrusterTuning(4),
  t5: buildThrusterTuning(5),
  t6: buildThrusterTuning(6),
  t7: buildThrusterTuning(7),
  t8: buildThrusterTuning(8)
};

// INPUT SHAPING
function inputDeadband(val, db) {
  return Math.abs(val) < db ? 0 : val;
}

let sway = -inputDeadband(ch.ch1 || 0, INPUT_DEADBAND);
let surge = inputDeadband(ch.ch2 || 0, INPUT_DEADBAND);

let heave = (c.heave_thrust !== undefined)
  ? inputDeadband(c.heave_thrust, 0.05) * 100
  : inputDeadband(ch.ch3 || 0, INPUT_DEADBAND);

let roll = inputDeadband(c.roll_thrust ?? 0, 0.05) * 100;
let pitch = inputDeadband(c.pitch_thrust ?? 0, 0.05) * 100;
let yaw = inputDeadband(c.yaw_thrust ?? 0, 0.05) * 100;

// MIXER
let thr1 = surge - sway - yaw;
let thr2 = surge + sway + yaw;
let thr3 = surge - sway + yaw;
let thr4 = surge + sway - yaw;

let thr5 = heave + roll + pitch;
let thr6 = heave - roll + pitch;
let thr7 = heave - roll - pitch;
let thr8 = heave + roll - pitch;

let thr = [thr1, thr2, thr3, thr4, thr5, thr6, thr7, thr8];

// FIRST NORMALISATION
const max_cmd = Math.max(...thr.map(Math.abs));
if (max_cmd > 100) {
  const scale = 100 / max_cmd;
  thr = thr.map(t => t * scale);
}

// DEADBAND COMP
function deadbandCompensate(val, fwd_db, rev_db) {
  if (val > ZERO_CUTOFF) {
    return fwd_db + (val / 100) * (100 - fwd_db);
  } else if (val < -ZERO_CUTOFF) {
    return -(rev_db + (Math.abs(val) / 100) * (100 - rev_db));
  }
  return 0;
}

thr[0] = deadbandCompensate(thr[0], TUNE.t1.deadband_fwd, TUNE.t1.deadband_rev);
thr[1] = deadbandCompensate(thr[1], TUNE.t2.deadband_fwd, TUNE.t2.deadband_rev);
thr[2] = deadbandCompensate(thr[2], TUNE.t3.deadband_fwd, TUNE.t3.deadband_rev);
thr[3] = deadbandCompensate(thr[3], TUNE.t4.deadband_fwd, TUNE.t4.deadband_rev);
thr[4] = deadbandCompensate(thr[4], TUNE.t5.deadband_fwd, TUNE.t5.deadband_rev);
thr[5] = deadbandCompensate(thr[5], TUNE.t6.deadband_fwd, TUNE.t6.deadband_rev);
thr[6] = deadbandCompensate(thr[6], TUNE.t7.deadband_fwd, TUNE.t7.deadband_rev);
thr[7] = deadbandCompensate(thr[7], TUNE.t8.deadband_fwd, TUNE.t8.deadband_rev);

// INVERT
function applyInvert(val, invert) {
  return invert ? -val : val;
}

thr[0] = applyInvert(thr[0], TUNE.t1.invert);
thr[1] = applyInvert(thr[1], TUNE.t2.invert);
thr[2] = applyInvert(thr[2], TUNE.t3.invert);
thr[3] = applyInvert(thr[3], TUNE.t4.invert);
thr[4] = applyInvert(thr[4], TUNE.t5.invert);
thr[5] = applyInvert(thr[5], TUNE.t6.invert);
thr[6] = applyInvert(thr[6], TUNE.t7.invert);
thr[7] = applyInvert(thr[7], TUNE.t8.invert);

// REVERSE GAIN (POST-INVERT)
function reverseCompensate(val, gain) {
  return (val < 0) ? val * gain : val;
}

thr[0] = reverseCompensate(thr[0], TUNE.t1.reverse_gain);
thr[1] = reverseCompensate(thr[1], TUNE.t2.reverse_gain);
thr[2] = reverseCompensate(thr[2], TUNE.t3.reverse_gain);
thr[3] = reverseCompensate(thr[3], TUNE.t4.reverse_gain);
thr[4] = reverseCompensate(thr[4], TUNE.t5.reverse_gain);
thr[5] = reverseCompensate(thr[5], TUNE.t6.reverse_gain);
thr[6] = reverseCompensate(thr[6], TUNE.t7.reverse_gain);
thr[7] = reverseCompensate(thr[7], TUNE.t8.reverse_gain);

// SECOND NORMALISATION (DISABLED FOR TESTING)
// const max_final = Math.max(...thr.map(Math.abs));
// if (max_final > 100) {
//   const scale_final = 100 / max_final;
//   thr = thr.map(t => t * scale_final);
// }

// CLAMP
function clampPercent(v) {
  return Math.max(-100, Math.min(100, Math.round(v)));
}

const thrClamped = armed ? thr.map(clampPercent) : [0,0,0,0,0,0,0,0];

// MQTT
const mqttMsg = {
  topic: `fleet/${fleet_id}/vessels/${vessel_id}/thrusters/set`,
  payload: {
    thr: thrClamped,
    armed
  }
};

// UDP
const vesselKey = String(vessel_id || "").trim().toLowerCase();

const udp_ip =
  flow.get(`udp_ip::${vesselKey}`) ||
  flow.get(`udp_ip::${vessel_id}`) ||
  null;

let craft_id = parseInt(
  flow.get(`udp_craft_id::${vesselKey}`) ??
  flow.get(`udp_craft_id::${vessel_id}`) ?? 1,
10);

if (!Number.isFinite(craft_id) || craft_id < 1) craft_id = 1;

if (!udp_ip) return [mqttMsg, null];

const buf = Buffer.alloc(18);
buf.writeUInt8(1, 0);
buf.writeUInt8(craft_id, 1);

for (let i = 0; i < 8; i++) {
  const val = Math.max(-1000, Math.min(1000, Math.round(thrClamped[i] * 10)));
  buf.writeInt16LE(val, 2 + i * 2);
}

const udpMsg = {
  payload: buf,
  ip: udp_ip,
  port: 14560
};

udpMsg._src = "rov_mixer";

return [mqttMsg, udpMsg];

// ═══════════════════════════════════════════════════════════
// Tender Flight Mode Mixer - MANUAL / STABLE / MAG (GPS)
// ═══════════════════════════════════════════════════════════
//
// OVERVIEW:
// ---------
// This node takes pilot stick inputs plus current navigation state
// (heading, GPS position, speed, sats, HDOP) and outputs corrected tender
// control commands.
//
// Modes:
//   MANUAL → direct stick passthrough, no corrections
//   STABLE → heading hold always; DP/GPS hold only when GPS lock is valid
//   MAG    → currently aliased to STABLE
//
// State is remembered between cycles using Node-RED context.
// Each vessel has its own stored state, keyed by vessel_id.
//
// LIVE TUNING:
// ------------
// Preferred tuning comes from flow context:
//
//   tuning::tender::heading_p
//   tuning::tender::heading_d
//   tuning::tender::yaw_min_corr
//   tuning::tender::heading_deadband_deg
//   tuning::tender::heading_taper_deg
//   tuning::tender::yaw_trim_rate
//
//   tuning::tender::dp_p
//   tuning::tender::dp_deadzone
//   tuning::tender::dp_max_correction
//   tuning::tender::dp_gps_slew
//   tuning::tender::dp_min_sats
//   tuning::tender::dp_max_hdop
//   tuning::tender::dp_velocity_damping
//   tuning::tender::dp_relock_after_pilot_ms
//
//   tuning::tender::input_deadband
//
// If a tuning key is missing or junk, safe defaults are used.
//
// ═══════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════
// DEFAULT TUNING VALUES
// ═══════════════════════════════════════════════════════════

const DEFAULTS = {
  // Heading controller gains (PD)
  heading_p: 0.70,
  heading_d: 0.08,
  yaw_corr_max: 55,

  // Heading shaping
  yaw_slew_per_cycle: 10.0,
  heading_deadband_deg: 1.0,
  heading_taper_deg: 5.0,
  yaw_min_corr: 8.0,

  // Pilot yaw trim
  yaw_trim_deadband: 5,
  yaw_trim_rate: 45, // deg/sec at full stick

  // GPS / DP hold
  dp_p: 2.0,
  dp_max_correction: 50,
  dp_deadzone: 1.5,
  dp_gps_slew: 5,
  dp_max_hdop: 1.8,
  dp_velocity_damping: 18.0,
  dp_relock_after_pilot_ms: 300,
  gps_jump_threshold: 10,

  // Local ENU approximation
  meters_per_deg_lat: 111000,
  meters_per_deg_lon: 88000,

  // Pilot override deadbands
  input_deadband: 5,
  yaw_corr_deadband: 5,

  // Minimum sats for DP
  dp_min_sats: 5
};

// ═══════════════════════════════════════════════════════════
// SAFE GETTERS
// ═══════════════════════════════════════════════════════════

function getNum(path, fallback) {
  const raw = flow.get(path);
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

// ═══════════════════════════════════════════════════════════
// LIVE PARAM SNAPSHOT
// ═══════════════════════════════════════════════════════════
//
// Build once per cycle so the whole controller uses a single
// consistent tuning snapshot.
//

const PARAMS = {
  // Heading controller
  HEADING_KP: getNum("tuning::tender::heading_p", DEFAULTS.heading_p),
  HEADING_KD: getNum("tuning::tender::heading_d", DEFAULTS.heading_d),
  YAW_CORR_MAX: DEFAULTS.yaw_corr_max,

  // Heading shaping
  YAW_SLEW_PER_CYCLE: DEFAULTS.yaw_slew_per_cycle,
  HEADING_DEADBAND_DEG: getNum("tuning::tender::heading_deadband_deg", DEFAULTS.heading_deadband_deg),
  HEADING_TAPER_DEG: getNum("tuning::tender::heading_taper_deg", DEFAULTS.heading_taper_deg),
  YAW_MIN_CORR: getNum("tuning::tender::yaw_min_corr", DEFAULTS.yaw_min_corr),

  // Pilot yaw trim
  YAW_TRIM_DEADBAND: DEFAULTS.yaw_trim_deadband,
  YAW_TRIM_RATE_MAX: getNum("tuning::tender::yaw_trim_rate", DEFAULTS.yaw_trim_rate),

  // GPS / DP hold
  POS_KP: getNum("tuning::tender::dp_p", DEFAULTS.dp_p),
  POS_MAX_CORRECTION: getNum("tuning::tender::dp_max_correction", DEFAULTS.dp_max_correction),
  POS_DEADZONE: getNum("tuning::tender::dp_deadzone", DEFAULTS.dp_deadzone),
  GPS_SLEW: getNum("tuning::tender::dp_gps_slew", DEFAULTS.dp_gps_slew),
  MAX_HDOP_FOR_DP: getNum("tuning::tender::dp_max_hdop", DEFAULTS.dp_max_hdop),
  VELOCITY_DAMPING: getNum("tuning::tender::dp_velocity_damping", DEFAULTS.dp_velocity_damping),
  RELOCK_AFTER_PILOT_MS: getNum("tuning::tender::dp_relock_after_pilot_ms", DEFAULTS.dp_relock_after_pilot_ms),
  GPS_JUMP_THRESHOLD: DEFAULTS.gps_jump_threshold,

  // Approx local metres/deg
  METERS_PER_DEG_LAT: DEFAULTS.meters_per_deg_lat,
  METERS_PER_DEG_LON: DEFAULTS.meters_per_deg_lon,

  // Pilot override deadbands
  FORWARD_DEADBAND: getNum("tuning::tender::input_deadband", DEFAULTS.input_deadband),
  STRAFE_DEADBAND: getNum("tuning::tender::input_deadband", DEFAULTS.input_deadband),
  YAW_CORR_DEADBAND: DEFAULTS.yaw_corr_deadband,

  // GPS validity
  MIN_SATS_FOR_DP: getNum("tuning::tender::dp_min_sats", DEFAULTS.dp_min_sats)
};

// ═══════════════════════════════════════════════════════════
// INPUTS
// ═══════════════════════════════════════════════════════════

const ch = msg.payload || {};
const vessel_id = msg.router?.vessel_id || "tender-01";

// ═══════════════════════════════════════════════════════════
// CONTEXT KEYS (PER VESSEL)
// ═══════════════════════════════════════════════════════════

const keyLast = `tender:lastMode:${vessel_id}`;
const keyHead = `tender:targetHeading:${vessel_id}`;
const keyLat = `tender:targetLat:${vessel_id}`;
const keyLon = `tender:targetLon:${vessel_id}`;
const keyTime = `tender:lastTimeMs:${vessel_id}`;
const keyLastErr = `tender:lastHeadingErr:${vessel_id}`;
const keyPrevYawCorr = `tender:prevYawCorr:${vessel_id}`;
const keyPrevFwd = `tender:prevForwardCorr:${vessel_id}`;
const keyPrevStrafe = `tender:prevStrafeCorr:${vessel_id}`;
const keyPrevNorth = `tender:prevNorthErr:${vessel_id}`;
const keyPrevEast = `tender:prevEastErr:${vessel_id}`;
const keyPilotGpsTs = `tender:lastPilotGpsTs:${vessel_id}`;

// ═══════════════════════════════════════════════════════════
// RESTORE STATE
// ═══════════════════════════════════════════════════════════

let lastMode = context.get(keyLast);
let targetHeading = context.get(keyHead);
let targetLat = context.get(keyLat);
let targetLon = context.get(keyLon);
let lastHeadingErr = context.get(keyLastErr) || 0;
let prevYawCorr = context.get(keyPrevYawCorr) || 0;
let prevForwardCorr = context.get(keyPrevFwd) || 0;
let prevStrafeCorr = context.get(keyPrevStrafe) || 0;

// ═══════════════════════════════════════════════════════════
// MODE NORMALIZE
// ═══════════════════════════════════════════════════════════
//
// MAG currently behaves the same as STABLE.
// Keeping the alias makes future MAG-specific logic easy later.
//

const modeIn = String(ch.flight_mode || "MANUAL").toUpperCase();
const mode = (modeIn === "MAG") ? "STABLE" : modeIn;

// ═══════════════════════════════════════════════════════════
// DELTA TIME
// ═══════════════════════════════════════════════════════════
//
// Used for yaw trim and heading derivative.
// Reject bad dt values from stalls, pauses, or clock jumps.
//

const nowMs = Date.now();
let lastTimeMs = context.get(keyTime);
let dt = 0;

if (typeof lastTimeMs === "number") {
  dt = (nowMs - lastTimeMs) / 1000;
  if (dt <= 0 || dt > 1) dt = 0;
}
context.set(keyTime, nowMs);

// ═══════════════════════════════════════════════════════════
// GPS LOCK VALIDITY
// ═══════════════════════════════════════════════════════════
//
// Treat obviously bogus 0,0 coordinates as invalid.
// Sats gate can be disabled by simply not providing sats.
//

const hasLatLon =
  typeof ch.lat === "number" &&
  typeof ch.lon === "number" &&
  !(Math.abs(ch.lat) < 0.0001 && Math.abs(ch.lon) < 0.0001);

const satsOk = (typeof ch.sats !== "number") || (ch.sats >= PARAMS.MIN_SATS_FOR_DP);
const hdopOk = (typeof ch.hdop !== "number") || ch.hdop <= PARAMS.MAX_HDOP_FOR_DP;
const gpsLock = hasLatLon && satsOk && hdopOk;

// ═══════════════════════════════════════════════════════════
// MODE TRANSITIONS
// ═══════════════════════════════════════════════════════════

if (mode === "STABLE" && lastMode !== "STABLE") {
  // Capture current heading as hold target when entering STABLE.
  if (typeof ch.heading === "number" && Number.isFinite(ch.heading)) {
    targetHeading = ch.heading;
    context.set(keyHead, targetHeading);
  }

  // Capture current GPS position only if lock is valid.
  if (gpsLock) {
    targetLat = ch.lat;
    targetLon = ch.lon;
    context.set(keyLat, targetLat);
    context.set(keyLon, targetLon);
  } else {
    targetLat = null;
    targetLon = null;
    context.set(keyLat, null);
    context.set(keyLon, null);
  }
}

if (mode === "MANUAL") {
  // Clear all hold targets and controller memory so nothing carries over.
  targetHeading = null;
  targetLat = null;
  targetLon = null;
  lastHeadingErr = 0;
  prevYawCorr = 0;
  prevForwardCorr = 0;
  prevStrafeCorr = 0;

  context.set(keyHead, null);
  context.set(keyLat, null);
  context.set(keyLon, null);
  context.set(keyLastErr, 0);
  context.set(keyPrevYawCorr, 0);
  context.set(keyPrevFwd, 0);
  context.set(keyPrevStrafe, 0);
  context.set(keyPrevNorth, null);
  context.set(keyPrevEast, null);
}

context.set(keyLast, mode);

// ═══════════════════════════════════════════════════════════
// RAW PILOT INPUTS
// ═══════════════════════════════════════════════════════════

let forward = (typeof ch.ch2 === "number") ? ch.ch2 : 0;
let strafe = (typeof ch.ch1 === "number") ? ch.ch1 : 0;
let yawIn = (typeof ch.ch4 === "number") ? ch.ch4 : 0;

let yawCorr = 0;
let forwardCorr = 0;
let strafeCorr = 0;
let northErrM = null;
let eastErrM = null;
let forwardErrM = null;
let strafeErrM = null;
let forwardVelMps = null;
let strafeVelMps = null;
let dpRelocking = false;

const pilotForwardActive = Math.abs(forward) > PARAMS.FORWARD_DEADBAND;
const pilotStrafeActive = Math.abs(strafe) > PARAMS.STRAFE_DEADBAND;

// ═══════════════════════════════════════════════════════════
// HEADING HOLD (STABLE)
// ═══════════════════════════════════════════════════════════

if (
  mode === "STABLE" &&
  typeof targetHeading === "number" &&
  typeof ch.heading === "number" &&
  Number.isFinite(ch.heading)
) {
  const currentHeading = ((ch.heading % 360) + 360) % 360;
  targetHeading = ((targetHeading % 360) + 360) % 360;

  if (Math.abs(yawIn) > PARAMS.YAW_TRIM_DEADBAND && dt > 0) {
    const yawNorm = Math.max(-100, Math.min(100, yawIn));
    const rateDegPerSec = (yawNorm / 100) * PARAMS.YAW_TRIM_RATE_MAX;

    targetHeading = (targetHeading + rateDegPerSec * dt + 360) % 360;
    context.set(keyHead, targetHeading);

    yawCorr = 0;
    lastHeadingErr = 0;
    context.set(keyLastErr, 0);
  } else {
    let err = targetHeading - currentHeading;
    err = (((err + 180) % 360) + 360) % 360 - 180;

    let errRate = 0;
    if (dt >= 0.02 && dt <= 0.3) {
      errRate = (err - lastHeadingErr) / dt;
    }

    lastHeadingErr = err;
    context.set(keyLastErr, err);

    const absErr = Math.abs(err);

    if (absErr <= PARAMS.HEADING_DEADBAND_DEG) {
      yawCorr = 0;
    } else {
      yawCorr = PARAMS.HEADING_KP * err + PARAMS.HEADING_KD * errRate;

      if (absErr < PARAMS.HEADING_TAPER_DEG && PARAMS.HEADING_TAPER_DEG > 0) {
        yawCorr *= (absErr / PARAMS.HEADING_TAPER_DEG);
      }

      yawCorr = Math.max(-PARAMS.YAW_CORR_MAX, Math.min(PARAMS.YAW_CORR_MAX, yawCorr));

      if (Math.abs(yawCorr) < PARAMS.YAW_MIN_CORR) {
        yawCorr = Math.sign(err) * PARAMS.YAW_MIN_CORR;
      }
    }

    if (Math.abs(yawIn) > PARAMS.YAW_CORR_DEADBAND) {
      yawCorr = 0;
    }
  }

  const yawDelta = yawCorr - prevYawCorr;
  if (Math.abs(yawDelta) > PARAMS.YAW_SLEW_PER_CYCLE) {
    yawCorr = prevYawCorr + Math.sign(yawDelta) * PARAMS.YAW_SLEW_PER_CYCLE;
  }

  prevYawCorr = yawCorr;
  context.set(keyPrevYawCorr, prevYawCorr);
}

// ═══════════════════════════════════════════════════════════
// GPS POSITION HOLD (STABLE ONLY)
// ═══════════════════════════════════════════════════════════

if (
  mode === "STABLE" &&
  gpsLock &&
  typeof targetLat === "number" &&
  typeof targetLon === "number" &&
  typeof ch.heading === "number" &&
  Number.isFinite(ch.heading)
) {
  const pilotMovingPosition = pilotForwardActive || pilotStrafeActive;

  if (pilotMovingPosition) {
    targetLat = ch.lat;
    targetLon = ch.lon;
    context.set(keyLat, targetLat);
    context.set(keyLon, targetLon);
    context.set(keyPilotGpsTs, nowMs);
    context.set(keyPrevNorth, null);
    context.set(keyPrevEast, null);
    context.set(keyPrevFwd, 0);
    context.set(keyPrevStrafe, 0);
    dpRelocking = true;
  } else {
    const lastPilotGpsTs = Number(context.get(keyPilotGpsTs) || 0);
    if (lastPilotGpsTs && nowMs - lastPilotGpsTs < PARAMS.RELOCK_AFTER_PILOT_MS) {
      targetLat = ch.lat;
      targetLon = ch.lon;
      context.set(keyLat, targetLat);
      context.set(keyLon, targetLon);
      dpRelocking = true;
    } else {
      const lat_err_deg = targetLat - ch.lat;
      const lon_err_deg = targetLon - ch.lon;
      const metersPerDegLon =
        PARAMS.METERS_PER_DEG_LAT * Math.cos((ch.lat * Math.PI) / 180);

      northErrM = lat_err_deg * PARAMS.METERS_PER_DEG_LAT;
      eastErrM = lon_err_deg * metersPerDegLon;

      const prevNorthErr = context.get(keyPrevNorth);
      const prevEastErr = context.get(keyPrevEast);
      const havePrev = (typeof prevNorthErr === "number") && (typeof prevEastErr === "number");

      if (!havePrev) {
        context.set(keyPrevNorth, northErrM);
        context.set(keyPrevEast, eastErrM);
        forwardCorr = 0;
        strafeCorr = 0;
      } else {
        const northDelta = Math.abs(northErrM - prevNorthErr);
        const eastDelta = Math.abs(eastErrM - prevEastErr);

        if (northDelta > PARAMS.GPS_JUMP_THRESHOLD || eastDelta > PARAMS.GPS_JUMP_THRESHOLD) {
          forwardCorr = 0;
          strafeCorr = 0;
        } else {
          context.set(keyPrevNorth, northErrM);
          context.set(keyPrevEast, eastErrM);

          const headingRad = (ch.heading * Math.PI) / 180;

          forwardErrM =
            northErrM * Math.cos(headingRad) +
            eastErrM * Math.sin(headingRad);

          strafeErrM =
            -northErrM * Math.sin(headingRad) +
            eastErrM * Math.cos(headingRad);

          if (Math.abs(forwardErrM) > PARAMS.POS_DEADZONE) {
            forwardCorr = forwardErrM * PARAMS.POS_KP;
          }

          if (Math.abs(strafeErrM) > PARAMS.POS_DEADZONE) {
            strafeCorr = strafeErrM * PARAMS.POS_KP;
          }

          if (typeof ch.speed === "number" && Number.isFinite(ch.speed) &&
            typeof ch.cog === "number" && Number.isFinite(ch.cog) &&
            ch.speed > 0.05) {
            const cogRad = (ch.cog * Math.PI) / 180;
            const northVel = ch.speed * Math.cos(cogRad);
            const eastVel = ch.speed * Math.sin(cogRad);
            forwardVelMps =
              northVel * Math.cos(headingRad) +
              eastVel * Math.sin(headingRad);
            strafeVelMps =
              -northVel * Math.sin(headingRad) +
              eastVel * Math.cos(headingRad);

            forwardCorr -= forwardVelMps * PARAMS.VELOCITY_DAMPING;
            strafeCorr -= strafeVelMps * PARAMS.VELOCITY_DAMPING;
          }

          forwardCorr = Math.max(-PARAMS.POS_MAX_CORRECTION, Math.min(PARAMS.POS_MAX_CORRECTION, forwardCorr));
          strafeCorr = Math.max(-PARAMS.POS_MAX_CORRECTION, Math.min(PARAMS.POS_MAX_CORRECTION, strafeCorr));

          forwardCorr = Math.max(prevForwardCorr - PARAMS.GPS_SLEW, Math.min(prevForwardCorr + PARAMS.GPS_SLEW, forwardCorr));
          strafeCorr = Math.max(prevStrafeCorr - PARAMS.GPS_SLEW, Math.min(prevStrafeCorr + PARAMS.GPS_SLEW, strafeCorr));

          context.set(keyPrevFwd, forwardCorr);
          context.set(keyPrevStrafe, strafeCorr);
        }
      }
    }
  }
} else {
  forwardCorr = 0;
  strafeCorr = 0;
  context.set(keyPrevFwd, 0);
  context.set(keyPrevStrafe, 0);
  context.set(keyPrevNorth, null);
  context.set(keyPrevEast, null);
}

// ═══════════════════════════════════════════════════════════
// PILOT OVERRIDE GATES
// ═══════════════════════════════════════════════════════════

if (pilotForwardActive) forwardCorr = 0;
if (pilotStrafeActive) strafeCorr = 0;

// ═══════════════════════════════════════════════════════════
// OUTPUT CONTROL COMMAND
// ═══════════════════════════════════════════════════════════

msg.control = {
  forward: forward + forwardCorr,
  strafe: strafe + strafeCorr,
  yaw: yawIn + yawCorr,
  target_heading: (typeof targetHeading === "number") ? targetHeading : null,
  heading_error: (typeof lastHeadingErr === "number") ? lastHeadingErr : null
};

flow.set(`target_heading::${vessel_id}`, msg.control.target_heading);

msg.tender_debug = {
  ts: nowMs,
  vessel_id,
  mode_in: modeIn,
  mode,
  gps_lock: gpsLock,
  sats_ok: satsOk,
  hdop_ok: hdopOk,
  has_latlon: hasLatLon,
  dp_relocking: dpRelocking,
  dt,
  targets: {
    heading: targetHeading,
    lat: targetLat,
    lon: targetLon
  },
  sensors: {
    heading: ch.heading,
    lat: ch.lat,
    lon: ch.lon,
    sats: ch.sats,
    hdop: ch.hdop,
    speed: ch.speed,
    cog: ch.cog
  },
  dp_error: {
    north_m: northErrM,
    east_m: eastErrM,
    forward_m: forwardErrM,
    strafe_m: strafeErrM,
    forward_vel_mps: forwardVelMps,
    strafe_vel_mps: strafeVelMps
  },
  inputs: {
    forward,
    strafe,
    yaw: yawIn
  },
  corrections: {
    yawCorr,
    forwardCorr,
    strafeCorr
  },
  tuning: {
    heading_p: PARAMS.HEADING_KP,
    heading_d: PARAMS.HEADING_KD,
    yaw_min_corr: PARAMS.YAW_MIN_CORR,
    heading_deadband_deg: PARAMS.HEADING_DEADBAND_DEG,
    heading_taper_deg: PARAMS.HEADING_TAPER_DEG,
    yaw_trim_rate: PARAMS.YAW_TRIM_RATE_MAX,
    dp_p: PARAMS.POS_KP,
    dp_deadzone: PARAMS.POS_DEADZONE,
    dp_max_correction: PARAMS.POS_MAX_CORRECTION,
    dp_gps_slew: PARAMS.GPS_SLEW,
    dp_min_sats: PARAMS.MIN_SATS_FOR_DP,
    dp_max_hdop: PARAMS.MAX_HDOP_FOR_DP,
    dp_velocity_damping: PARAMS.VELOCITY_DAMPING,
    dp_relock_after_pilot_ms: PARAMS.RELOCK_AFTER_PILOT_MS,
    input_deadband: PARAMS.FORWARD_DEADBAND
  },
  output: msg.control
};

return msg;

// ═══════════════════════════════════════════════════════════════════════════
// TENDER 3-THRUSTER MIXER WITH LIVE TUNING,
// REVERSE GAIN, SWAY ASYMMETRY COMPENSATION, AND INVERT FLAGS
// ═══════════════════════════════════════════════════════════════════════════
//
// PURPOSE:
// --------
// Converts tender control commands into 3 individual thruster outputs.
//
// INPUTS:
// -------
// From flight mode mixer (msg.control):
//   - control.forward → surge command [-100, 100]
//   - control.strafe  → sway command  [-100, 100]
//   - control.yaw     → yaw command   [-100, 100]
//
// From stick channels (msg.payload):
//   - ch5 → ARM switch: >0 = armed, <=0 = disarmed
//
// LIVE TUNING SOURCES:
// --------------------
// Synced from Home Assistant into flow context:
//
//   tuning::tender::input_deadband
//   tuning::tender::sway_left_gain
//   tuning::tender::sway_right_gain
//
//   tuning::tender::t1_reverse_gain
//   tuning::tender::t2_reverse_gain
//   tuning::tender::t3_reverse_gain
//
//   tuning::tender::t1_invert
//   tuning::tender::t2_invert
//   tuning::tender::t3_invert
//
// If a helper is missing or invalid, safe defaults are used.
//
// OUTPUTS:
// --------
// return[0] = MQTT debug / sim output
// return[1] = UDP binary packet
//
// THRUSTER LAYOUT (TOP VIEW, BOW UP):
// -----------------------------------
//
//            [ Bow Thruster ]   T1
//                  ↑ +FWD
//                  |
//   [ Port Aft ]        [ Starboard Aft ]
//       T2                    T3
//
// SIGN CONVENTIONS:
// -----------------
// +forward = bow direction
// +strafe  = starboard
// +yaw     = clockwise from above
//
// NOTE:
// -----
// Packet format matches the shared ESPHome component.
// Tender uses T1..T3 only.
// T4..T8 are padded with zeros.
//
// ═══════════════════════════════════════════════════════════════════════════

// Hard kill.
if (flow.get("safety_kill_active") === true) return null;

// ═══════════════════════════════════════════════════════════
// INPUT EXTRACTION
// ═══════════════════════════════════════════════════════════

const ch = msg.payload || {};
const c = msg.control || {};
const fleet_id = msg.router?.fleet_id || '';
const vessel_id = msg.router?.vessel_id || 'tender-01';

// Armed only when CH5 > 0.
// When disarmed we still send zeros to keep the remote deadman alive.
const armed = (ch.ch5 || 0) > 0;

// ═══════════════════════════════════════════════════════════
// DEFAULT TUNING VALUES
// ═══════════════════════════════════════════════════════════

const DEFAULTS = {
  zero_cutoff: 2.0,
  input_deadband: 2.0,

  reverse_gain: 1.30,

  sway_right_gain: 2.00,
  sway_left_gain: 1.30,

  t1_invert: false,
  t2_invert: false,
  t3_invert: false,

  bow_mount_gain: 1.0,
  port_mount_gain: 1.0,
  star_mount_gain: 1.0
};

// ═══════════════════════════════════════════════════════════
// SAFE GETTERS
// ═══════════════════════════════════════════════════════════

function getNum(path, fallback) {
  const raw = flow.get(path);
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

function getBool(path, fallback = false) {
  const raw = flow.get(path);

  if (raw === true || raw === false) return raw;
  if (raw === 1 || raw === "1") return true;
  if (raw === 0 || raw === "0") return false;

  const s = String(raw).trim().toLowerCase();
  if (s === "on" || s === "true") return true;
  if (s === "off" || s === "false") return false;

  return fallback;
}

// ═══════════════════════════════════════════════════════════
// LIVE PARAM SNAPSHOT
// ═══════════════════════════════════════════════════════════

const ZERO_CUTOFF = getNum("tuning::tender::input_deadband", DEFAULTS.zero_cutoff);

const SWAY_RIGHT_GAIN = getNum("tuning::tender::sway_right_gain", DEFAULTS.sway_right_gain);
const SWAY_LEFT_GAIN  = getNum("tuning::tender::sway_left_gain", DEFAULTS.sway_left_gain);

const BOW_MOUNT_GAIN  = DEFAULTS.bow_mount_gain;
const PORT_MOUNT_GAIN = DEFAULTS.port_mount_gain;
const STAR_MOUNT_GAIN = DEFAULTS.star_mount_gain;

const TUNE = {
  t1: {
    reverse_gain: getNum("tuning::tender::t1_reverse_gain", DEFAULTS.reverse_gain),
    invert: getBool("tuning::tender::t1_invert", DEFAULTS.t1_invert)
  },
  t2: {
    reverse_gain: getNum("tuning::tender::t2_reverse_gain", DEFAULTS.reverse_gain),
    invert: getBool("tuning::tender::t2_invert", DEFAULTS.t2_invert)
  },
  t3: {
    reverse_gain: getNum("tuning::tender::t3_reverse_gain", DEFAULTS.reverse_gain),
    invert: getBool("tuning::tender::t3_invert", DEFAULTS.t3_invert)
  }
};

// ═══════════════════════════════════════════════════════════
// INPUT EXTRACTION + NOISE KILL
// ═══════════════════════════════════════════════════════════
//
// Kill tiny noise around zero before mixing.
// This gives a cleaner centre feel and reduces twitching.
//

let f = Number(c.forward || 0);
let s = Number(c.strafe || 0);
let y = Number(c.yaw || 0);

if (!Number.isFinite(f)) f = 0;
if (!Number.isFinite(s)) s = 0;
if (!Number.isFinite(y)) y = 0;

if (Math.abs(f) < ZERO_CUTOFF) f = 0;
if (Math.abs(s) < ZERO_CUTOFF) s = 0;
if (Math.abs(y) < ZERO_CUTOFF) y = 0;

// ═══════════════════════════════════════════════════════════
// SWAY ASYMMETRY COMPENSATION
// ═══════════════════════════════════════════════════════════
//
// If the hull / thruster geometry gives different sway authority left vs right,
// apply directional gain here before the mixer.
//

const sway_gain = (s >= 0) ? SWAY_RIGHT_GAIN : SWAY_LEFT_GAIN;
const s_compensated = s * sway_gain;

// ═══════════════════════════════════════════════════════════
// MIXER
// ═══════════════════════════════════════════════════════════
//
// T1 bow thruster mainly handles sway + yaw.
// T2/T3 aft thrusters handle forward + yaw + sway.
//

let bow  = (-s_compensated - y) * BOW_MOUNT_GAIN;
let port = (f + y - s_compensated) * PORT_MOUNT_GAIN;
let star = (f - y + s_compensated) * STAR_MOUNT_GAIN;

// ═══════════════════════════════════════════════════════════
// FIRST NORMALISATION
// ═══════════════════════════════════════════════════════════
//
// Keep raw mixed outputs inside +/-100 before compensation.
//

const max_cmd = Math.max(Math.abs(bow), Math.abs(port), Math.abs(star));
if (max_cmd > 100) {
  const scale = 100 / max_cmd;
  bow *= scale;
  port *= scale;
  star *= scale;
}

// ═══════════════════════════════════════════════════════════
// REVERSE GAIN COMPENSATION
// ═══════════════════════════════════════════════════════════
//
// If reverse is weaker than forward, boost negative outputs.
//

function reverseCompensate(val, gain) {
  return (val < 0) ? val * gain : val;
}

bow  = reverseCompensate(bow,  TUNE.t1.reverse_gain);
port = reverseCompensate(port, TUNE.t2.reverse_gain);
star = reverseCompensate(star, TUNE.t3.reverse_gain);

// ═══════════════════════════════════════════════════════════
// INVERT FLAGS
// ═══════════════════════════════════════════════════════════
//
// Used to correct wiring / motor direction without touching mixer math.
//

function applyInvert(val, invert) {
  return invert ? -val : val;
}

bow  = applyInvert(bow,  TUNE.t1.invert);
port = applyInvert(port, TUNE.t2.invert);
star = applyInvert(star, TUNE.t3.invert);

// ═══════════════════════════════════════════════════════════
// SECOND NORMALISATION
// ═══════════════════════════════════════════════════════════
//
// Compensation or inversion can push outputs past +/-100 again.
//

const max_final = Math.max(Math.abs(bow), Math.abs(port), Math.abs(star));
if (max_final > 100) {
  const scale_final = 100 / max_final;
  bow *= scale_final;
  port *= scale_final;
  star *= scale_final;
}

// Snap tiny outputs back to exact zero to avoid creep.
if (Math.abs(bow) < ZERO_CUTOFF) bow = 0;
if (Math.abs(port) < ZERO_CUTOFF) port = 0;
if (Math.abs(star) < ZERO_CUTOFF) star = 0;

// ═══════════════════════════════════════════════════════════
// CLAMP + ARM GATE
// ═══════════════════════════════════════════════════════════

function clampPercent(v) {
  return Math.max(-100, Math.min(100, Math.round(v)));
}

const thrClamped = armed
  ? [clampPercent(bow), clampPercent(port), clampPercent(star)]
  : [0, 0, 0];

// ═══════════════════════════════════════════════════════════
// CRAFT ID RESOLVE
// ═══════════════════════════════════════════════════════════

const vesselKey = String(vessel_id || "").trim().toLowerCase();

const rawCraft =
  flow.get(`udp_craft_id::${vesselKey}`) ??
  flow.get(`udp_craft_id::${vessel_id}`) ??
  1;

let craft_id = parseInt(rawCraft, 10);
if (!Number.isFinite(craft_id) || craft_id < 1) craft_id = 1;

// Cache latest output for replay / cross-vessel logic.
flow.set(`veh_last::${vessel_id}`, {
  fleet_id,
  vessel_id,
  thr: thrClamped,
  craft_type: 2, // Tender
  craft_id,
  ts: Date.now()
});

// ═══════════════════════════════════════════════════════════
// OUTPUT 0: MQTT DEBUG / SIM
// ═══════════════════════════════════════════════════════════

const mqttMsg = {
  topic: `fleet/${fleet_id}/vessels/${vessel_id}/thrusters/set`,
  payload: {
    thr: thrClamped,
    armed
  }
};

// ═══════════════════════════════════════════════════════════
// OUTPUT 1: UDP BINARY PACKET
// ═══════════════════════════════════════════════════════════

const udp_ip =
  flow.get(`udp_ip::${vesselKey}`) ||
  flow.get(`udp_ip::${vessel_id}`) ||
  null;

// Quiet-ish warning if target IP not ready yet.
if (!udp_ip) {
  const warnKey = `udp_warn_ts::${vesselKey}`;
  const lastWarn = flow.get(warnKey) || 0;
  const WARN_EVERY_MS = 20000;

  if (Date.now() - lastWarn > WARN_EVERY_MS) {
    node.warn(`No UDP IP for vessel=${vessel_id} (key=${vesselKey}) - dropping UDP packet`);
    flow.set(warnKey, Date.now());
  }

  return [mqttMsg, null];
}

// Packet format shared with ROV:
//   byte 0: craft_type = 2 (Tender)
//   byte 1: craft_id
//   bytes 2-7: T1..T3 as int16LE scaled x10
//   bytes 8-17: T4..T8 = 0
const buf = Buffer.alloc(18);
buf.writeUInt8(2, 0);
buf.writeUInt8(craft_id, 1);

for (let i = 0; i < 3; i++) {
  const val = Math.max(-1000, Math.min(1000, Math.round(thrClamped[i] * 10)));
  buf.writeInt16LE(val, 2 + i * 2);
}

const udpMsg = {
  payload: buf,
  ip: udp_ip,
  port: 14560
};

// Debug block for UI / MQTT debug / sidebar
msg.tender_mixer_debug = {
  vessel_id,
  armed,
  inputs: {
    forward: f,
    strafe: s,
    yaw: y,
    strafe_compensated: s_compensated
  },
  tuning: {
    zero_cutoff: ZERO_CUTOFF,
    sway_left_gain: SWAY_LEFT_GAIN,
    sway_right_gain: SWAY_RIGHT_GAIN,
    thrusters: TUNE
  },
  outputs: {
    bow,
    port,
    star,
    thr: thrClamped
  },
  udp: {
    ip: udp_ip,
    port: 14560,
    craft_id
  }
};

// Actual output order:
//   [0] MQTT
//   [1] UDP

udpMsg._src = "tender_mixer";

return [mqttMsg, udpMsg];

// === Fleet Manifest Dumper ===
// Reads manifest from global context and outputs to debug

const manifest = global.get("fleet_manifest");

if (!manifest) {
    node.warn("⚠️ No manifest found in global context");
    return null;
}

// Dump summary
node.log(`📦 Fleet manifest dump: fleet_id=${manifest.fleet_id}, devices=${Object.keys(manifest.devices).length}`);

// Send full manifest as msg.payload
msg.payload = manifest;
return msg;

// Handles bootstrap/status/{node_name or MAC} → online/offline
// ADDED: Clear udp_ip::{vessel_id} when a driver device goes offline

const parts = (msg.topic || '').split('/');
if (parts.length < 3) return null;

const identifier = parts[2]; // Could be node_name or MAC
const status = msg.payload === 'online' ? 'online' : 'offline';

// Load manifest to map node_name → MAC and get device info
const manifest = global.get('fleet_manifest');
let mac = identifier;
let deviceInfo = null;

if (manifest && manifest.devices) {
    for (const [k, v] of Object.entries(manifest.devices)) {
        // Match by MAC key
        if (k.toUpperCase() === identifier.toUpperCase()) {
            deviceInfo = v;
            mac = k.toUpperCase();
            break;
        }
        // Match by name
        if (v.name === identifier) {
            deviceInfo = v;
            mac = k.toUpperCase();
            break;
        }
    }
}

// Update fleet table
let table = flow.get('fleet_table') || [];
let idx = table.findIndex(e => e.device_id === mac);

if (idx >= 0) {
    table[idx].status = status;
    table[idx].last_seen = new Date().toLocaleString();
}

flow.set('fleet_table', table);

// === Clear UDP IP when driver goes offline ===
if (status === 'offline' && deviceInfo) {
    const roles = Array.isArray(deviceInfo.role) ? deviceInfo.role : [deviceInfo.role];

    if (roles.includes('driver') && deviceInfo.vessel_id) {
        const vessel_id = deviceInfo.vessel_id;
        flow.set(`udp_ip::${vessel_id}`, null);
        flow.set(`udp_hostname::${vessel_id}`, null);
        node.log(`UDP: cleared IP for vessel=${vessel_id} (${deviceInfo.name} offline)`);
    }
}

return { payload: table };

const lastChannels = flow.get("last_channels") || {};
const r = flow.get("last_router");
const ts = Number(flow.get("last_router_ts") || 0);
if (!r || !r.vessel_id) return null;
if (Date.now() - ts > 200) return null;

msg.payload = lastChannels;
msg.router = r;

if (r.vessel_id !== "rov-02") {
    const rovChannels = flow.get("last_rov_channels") || {};
    const rad2deg = 180 / Math.PI;

    const rovMsg = {
    payload: Object.assign({}, rovChannels, {
        heading: Number(flow.get("nav::rov-02::heading") || 0),
        pitch: Number(flow.get("nav::rov-02::pitch") || 0),
        roll: Number(flow.get("nav::rov-02::roll") || 0),
        depth: Number(flow.get("nav::rov-02::depth") || 0),
        pitch_rate: Number(flow.get("nav::rov-02::pitch_rate") || 0),
        roll_rate: Number(flow.get("nav::rov-02::roll_rate") || 0),
        yaw_rate: Number(flow.get("nav::rov-02::yaw_rate") || 0),
        lat: Number(flow.get("nav::rov-02::lat") || 0),
        lon: Number(flow.get("nav::rov-02::lon") || 0),
        sog: Number(flow.get("nav::rov-02::sog") || 0),
        speed: Number(flow.get("nav::rov-02::speed") || 0),
        sats: Number(flow.get("nav::rov-02::sats") || 0)
    }),
        router: { fleet_id: r.fleet_id, vessel_id: "rov-02", kind: "rov", roles: ["driver"] }
    };

    return [rovMsg, msg];
}

return [null, msg];

// ═══════════════════════════════════════════════════════════
// Merge Device Orientations to Vessel (SignalK Format)
// ═══════════════════════════════════════════════════════════
// Purpose: Aggregate orientation data from multiple devices on
//          a vessel into SignalK-compliant vessel navigation data
// ═══════════════════════════════════════════════════════════
// Merge Device Attitudes to Vessel Navigation
// ═══════════════════════════════════════════════════════════
// Input:
//   fleet/{fleet}/vessels/{vessel}/devices/{device}/navigation/attitude
//
// Output:
//   fleet/{fleet}/vessels/{vessel}/navigation/attitude
//   fleet/{fleet}/vessels/{vessel}/navigation/headingTrue
//
// Notes:
// - attitude payload is { pitch, roll, yaw } in radians
// - headingTrue payload is { value } in radians
// - pitch/roll are linearly averaged
// - yaw is circularly averaged
// ═══════════════════════════════════════════════════════════
// --- Parse incoming topic ---
// Expected format: fleet/{fleet}/vessels/{vessel}/devices/{device}/navigation/attitude
const parts = (msg.topic || '').split('/');
if (parts.length < 8 || parts[0] !== 'fleet' || parts[2] !== 'vessels' || parts[4] !== 'devices') return null;

const fleet_id = parts[1];    // Extract fleet identifier
const vessel_id = parts[3];   // Extract vessel identifier
const device_id = parts[5];   // Extract device identifier (MAC)

// --- Extract attitude data from payload (SignalK format: radians) ---
const att = msg.payload || {};

// --- Store this device's data in flow context ---
const key = `device_nav::${vessel_id}::${device_id}`;
flow.set(key, {
    pitch: Number(att.pitch) || 0,     // Radians
    roll: Number(att.roll) || 0,       // Radians
    yaw: Number(att.yaw) || 0,         // Radians (heading true)
    ts: Date.now()
});

// --- Gather all device data for this vessel ---
const allKeys = flow.keys().filter(k => k.startsWith(`device_nav::${vessel_id}::`));

// Only use data less than 2 seconds old
const devices = allKeys
    .map(k => flow.get(k))
    .filter(d => d && (Date.now() - d.ts) < 2000);

if (devices.length === 0) return null;

// --- Average linear values (pitch, roll) ---
const avg_pitch = devices.reduce((sum, d) => sum + d.pitch, 0) / devices.length;
const avg_roll = devices.reduce((sum, d) => sum + d.roll, 0) / devices.length;

// --- Circular average for heading (yaw) ---
// Convert from radians to sin/cos, average, convert back
const sin_sum = devices.reduce((sum, d) => sum + Math.sin(d.yaw), 0);
const cos_sum = devices.reduce((sum, d) => sum + Math.cos(d.yaw), 0);
const avg_yaw = Math.atan2(sin_sum, cos_sum);  // Result in radians

// Round to 4 decimal places
const round = (v) => Math.round(v * 10000) / 10000;

// --- Publish multiple SignalK navigation messages ---
// We'll return an array of messages to send to different topics
return [
    // Attitude (pitch, roll, yaw in radians)
    {
        topic: `fleet/${fleet_id}/vessels/${vessel_id}/navigation/attitude`,
        payload: {
            pitch: round(avg_pitch),
            roll: round(avg_roll),
            yaw: round(avg_yaw)
        }
    },
    // Heading True (just the yaw value)
    {
        topic: `fleet/${fleet_id}/vessels/${vessel_id}/navigation/headingTrue`,
        payload: {
            value: round(avg_yaw)
        }
    }
];

// Merge magnetic heading from devices
// Input: fleet/{fleet}/vessels/{vessel}/devices/{device}/navigation/headingMagnetic
const parts = (msg.topic || '').split('/');
if (parts.length < 8) return null;

const fleet_id = parts[1];
const vessel_id = parts[3];
const device_id = parts[5];

const key = `device_hmag::${vessel_id}::${device_id}`;
flow.set(key, {
    heading: Number(msg.payload.value) || 0,  // Radians
    ts: Date.now()
});

// Gather and average
const allKeys = flow.keys().filter(k => k.startsWith(`device_hmag::${vessel_id}::`));
const devices = allKeys.map(k => flow.get(k)).filter(d => d && (Date.now() - d.ts) < 2000);

if (devices.length === 0) return null;

// Circular average
const sin_sum = devices.reduce((sum, d) => sum + Math.sin(d.heading), 0);
const cos_sum = devices.reduce((sum, d) => sum + Math.cos(d.heading), 0);
const avg_heading = Math.atan2(sin_sum, cos_sum);

return {
    topic: `fleet/${fleet_id}/vessels/${vessel_id}/navigation/headingMagnetic`,
    payload: {
        value: Math.round(avg_heading * 10000) / 10000
    }
};

// ═══════════════════════════════════════════════════════════
// Merge Signal K Navigation Data into Channels (UPDATED)
// ═══════════════════════════════════════════════════════════
// Combines vessel-level nav topics into flow context for mixers,
// autopilot, hold modes, UI, etc.
//
// Expected vessel topics:
//   fleet/{fleet}/vessels/{vessel}/navigation/attitude
//   fleet/{fleet}/vessels/{vessel}/navigation/headingTrue
//   fleet/{fleet}/vessels/{vessel}/navigation/rateOfTurn
//   fleet/{fleet}/vessels/{vessel}/navigation/position
//   fleet/{fleet}/vessels/{vessel}/navigation/speedOverGround
//   fleet/{fleet}/vessels/{vessel}/navigation/courseOverGroundTrue
//   fleet/{fleet}/vessels/{vessel}/navigation/gnss
//
// Depth now comes in as:
//   fleet/{fleet}/vessels/{vessel}/navigation/depthBelowTransducer
//
// Units:
//   attitude / heading / COG / rateOfTurn = radians / rad/s
//   stored in flow as radians so the router can make one consistent
//   conversion to controller-facing degrees.
// ═══════════════════════════════════════════════════════════
const parts = (msg.topic || '').split('/');
if (parts.length < 6 || parts[0] !== 'fleet' || parts[2] !== 'vessels') return null;

const vessel_id = parts[3];
const category = parts[4];
const leaf = parts[5];

if (category !== 'navigation') return null;

if (leaf === 'attitude') {
    const att = msg.payload || {};
    flow.set(`nav::${vessel_id}::pitch`, Number(att.pitch) || 0);
    flow.set(`nav::${vessel_id}::roll`,  Number(att.roll)  || 0);
    flow.set(`nav::${vessel_id}::heading`, Number(att.yaw) || 0);

} else if (leaf === 'headingTrue') {
    const h = Number(msg.payload.value) || 0;
    flow.set(`nav::${vessel_id}::heading`, h);

} else if (leaf === 'rateOfTurn') {
    const rot = Number(msg.payload.value) || 0;
    flow.set(`nav::${vessel_id}::yaw_rate`, rot);

} else if (leaf === 'position') {
    const pos = msg.payload || {};
    flow.set(`nav::${vessel_id}::lat`, Number(pos.latitude)  || 0);
    flow.set(`nav::${vessel_id}::lon`, Number(pos.longitude) || 0);
    flow.set(`nav::${vessel_id}::alt`, Number(pos.altitude)  || 0);

} else if (leaf === 'speedOverGround') {
