} else if (leaf === 'courseOverGroundTrue') {
    const cog = Number(msg.payload.value) || 0;
    flow.set(`nav::${vessel_id}::cog`, cog);

} else if (leaf === 'gnss') {
    const sats = Number(msg.payload.count) || 0;
    flow.set(`nav::${vessel_id}::sats`, sats);
    const hdop = Number(msg.payload.hdop ?? msg.payload.horizontalDilution ?? msg.payload.horizontal_dilution);
    if (Number.isFinite(hdop)) flow.set(`nav::${vessel_id}::hdop`, hdop);

} else if (leaf === 'depthBelowTransducer') {
    const depth = Number(msg.payload.value) || 0;
    flow.set(`nav::${vessel_id}::depth`, depth);
}

return null;

// Simulate depth sensor for ROV using new standard
const vessel_id = 'rov-02';
const fleet_id = 'NZAAT2510';
const device_id = 'simulator';

const time = Date.now() / 1000;
