if (devices.length === 0) return null;

const avg_yaw_rate = devices.reduce((sum, d) => sum + d.yaw_rate, 0) / devices.length;

return {
    topic: `fleet/${fleet_id}/vessels/${vessel_id}/navigation/rateOfTurn`,
