const devices = allKeys
    .map(k => flow.get(k))
    .filter(d => d && (Date.now() - d.ts) < 5000);

if (devices.length === 0) return null;

// Average SOG
const avg_sog = devices.reduce((sum, d) => sum + d.sog, 0) / devices.length;

// Store in flow context
flow.set(`nav::${vessel_id}::sog`, avg_sog);

// Republish
return {
    topic: `fleet/${fleet_id}/vessels/${vessel_id}/navigation/speedOverGround`,
    payload: {
        value: Math.round(avg_sog * 1000) / 1000
    }
};

// Merge COG from all devices (circular average)
const parts = (msg.topic || '').split('/');
if (parts.length < 8 || parts[0] !== 'fleet' || parts[2] !== 'vessels') return null;

const fleet_id = parts[1];
const vessel_id = parts[3];
const device_id = parts[5];

// Store device COG (value is in radians)
const key = `device_cog::${vessel_id}::${device_id}`;
flow.set(key, {
    cog: Number(msg.payload.value) || 0,
    ts: Date.now()
});

// Gather all devices
