const devices = allKeys
    .map(k => flow.get(k))
    .filter(d => d && (Date.now() - d.ts) < 5000);

if (devices.length === 0) return null;

// Circular average for COG (radians)
const sin_sum = devices.reduce((sum, d) => sum + Math.sin(d.cog), 0);
const cos_sum = devices.reduce((sum, d) => sum + Math.cos(d.cog), 0);
const avg_cog = Math.atan2(sin_sum, cos_sum);

// Store in flow context in radians. The router converts once for controllers.
flow.set(`nav::${vessel_id}::cog`, avg_cog);

// Republish (in radians per SignalK)
return {
    topic: `fleet/${fleet_id}/vessels/${vessel_id}/navigation/courseOverGroundTrue`,
    payload: {
        value: Math.round(avg_cog * 10000) / 10000
    }
