// Gather all devices
const allKeys = flow.keys().filter(k => k.startsWith(`device_sats::${vessel_id}::`));
const devices = allKeys
    .map(k => flow.get(k))
    .filter(d => d && (Date.now() - d.ts) < 5000);

if (devices.length === 0) return null;

// Use maximum sat count (best fix) OR average
const max_sats = Math.max(...devices.map(d => d.sats));
const hdops = devices.map(d => d.hdop).filter(v => Number.isFinite(v) && v > 0);
const best_hdop = hdops.length ? Math.min(...hdops) : null;

// Store in flow context
flow.set(`nav::${vessel_id}::sats`, max_sats);
if (best_hdop !== null) {
    flow.set(`nav::${vessel_id}::hdop`, best_hdop);
}

// Republish
return {
    topic: `fleet/${fleet_id}/vessels/${vessel_id}/navigation/gnss`,
    payload: {
