// ═══════════════════════════════════════════════════════════
// TARGET HEADING PUBLISHER
// ═══════════════════════════════════════════════════════════
//
// PURPOSE:
// --------
// Publishes the current target heading for a vessel to MQTT.
//
// This allows:
//   - UI display (dashboard, gauges)
//   - logging / Grafana
//   - debugging heading hold behaviour
//
// SOURCE PRIORITY:
// ----------------
// 1. msg.control.target_heading (live from mixer)
// 2. flow context fallback (last known value)
//
// WHY:
// ----
// During low update rates or partial flows, msg.control may not
// always carry target_heading — so we fall back to cached value.
//
// OUTPUT:
// -------
// topic:
//   fleet/{fleet_id}/vessels/{vessel_id}/control/target_heading
//
// payload:
// {
//   target_heading: number (deg, 0–360),
//   ts: unix ms timestamp
// }
//
// SAFETY:
// -------
// - Rejects invalid / NaN / missing values
// - Does NOT publish junk data
//
// ═══════════════════════════════════════════════════════════


// Extract router info (required for topic structure)
const router = msg.router || {};
if (!router.fleet_id || !router.vessel_id) return null;


// Prefer live heading from control output,
// fallback to last known value stored in flow context
const raw =
    (msg.control && typeof msg.control.target_heading === "number")
        ? msg.control.target_heading
        : flow.get(`target_heading::${router.vessel_id}`);


// Force numeric conversion (handles strings too)
const th = Number(raw);

// Reject invalid values (NaN, undefined, null, etc)
if (!Number.isFinite(th)) return null;


// Publish clean, rounded heading
return {
    topic: `fleet/${router.fleet_id}/vessels/${router.vessel_id}/control/target_heading`,
    payload: {
        target_heading: Number(th.toFixed(2)), // limit noise
        ts: Date.now()
    }
};

flow.set("udp_ip::rov-02", "172.16.10.20");
flow.set("udp_ip::tender-01", "172.16.10.30");
return null;

// ═══════════════════════════════════════════════════════════
// ROV Axis Clamp + Debug
// ═══════════════════════════════════════════════════════════
//
// PURPOSE
// -------
// Safety clamp layer between the ROV flight controller and
// the thruster mixer.
//
// This node:
//   1. Passes MANUAL mode through unchanged
//   2. Clamps stabilization outputs in STABLE / MAG
//   3. Publishes a debug snapshot for tuning / diagnosis
//
// WHY THIS EXISTS
// ---------------
// The upstream flight-mode controller outputs normalized axis
// commands in msg.control:
//
//   roll_thrust
//   pitch_thrust
//   yaw_thrust
//   heave_thrust
//
// The thruster mixer later multiplies these by 100.
//
// Without a clamp layer, a bad sign, bad sensor, or aggressive
// gain can slam an axis and make the vehicle go mental.
//
// IMPORTANT BEHAVIOUR
// -------------------
// MANUAL mode:
//   - NO axis clamp applied
//   - pilot gets full authority
//
// STABLE / MAG modes:
//   - stabilization outputs are clamped
//   - prevents runaway control effort
//
// LIVE TUNING
// -----------
// Preferred live values come from flow context:
//
//   tuning::rov::axis_clamp_roll
//   tuning::rov::axis_clamp_pitch
//   tuning::rov::axis_clamp_yaw
//   tuning::rov::axis_clamp_heave
//
// Legacy support is still kept for:
//
//   flow.get("rov_limits")
//   flow.get("rov_tuning_limits")
//
// Example legacy object:
// {
//   max_roll_correction: 0.35,
//   max_pitch_correction: 0.35,
//   max_yaw_correction: 0.30,
//   max_heave_correction: 1.00
// }
//
// NOTES
// -----
// • Values are normalized in range about [-1.0, +1.0]
// • 0.30 means about 30% axis command after mixer scaling
// • Manual mode bypasses clamps completely
//
// ═══════════════════════════════════════════════════════════

// Normalise incoming control object so all expected keys exist.
const c = Object.assign({
    roll_thrust: 0,
    pitch_thrust: 0,
    yaw_thrust: 0,
    heave_thrust: 0
}, msg.control || {});

// Flight mode drives whether clamp is active.
const mode = String(msg.payload?.flight_mode || "MANUAL").toUpperCase();

// Built-in safe defaults.
// These are used if neither live tuning nor legacy objects exist.
const defaults = {
    max_roll_correction: 0.35,
    max_pitch_correction: 0.35,
    max_yaw_correction: 0.30,
    max_heave_correction: 1.00
};

// ───────────────────────────────────────────────────────────
// SAFE GETTERS
// ───────────────────────────────────────────────────────────

function getNum(path, fallback) {
    const raw = flow.get(path);
    const n = Number(raw);
    return Number.isFinite(n) ? n : fallback;
}

// Clamp helper.
// Returns 0 if input or clamp limit is bad.
function clampAxis(v, maxAbs) {
    const n = Number(v || 0);
    const m = Math.abs(Number(maxAbs || 0));

    if (!Number.isFinite(n)) return 0;
    if (!Number.isFinite(m) || m <= 0) return 0;

    return Math.max(-m, Math.min(m, n));
}

// ───────────────────────────────────────────────────────────
// RESOLVE LIMITS
// ───────────────────────────────────────────────────────────
//
// Order of precedence:
//   1. defaults
//   2. legacy flow objects
//   3. live helper-driven tuning::rov::* values
//
// That lets you migrate cleanly without breaking older flows.
//

const legacyLimits = Object.assign(
    {},
    flow.get("rov_limits") || {},
    flow.get("rov_tuning_limits") || {}
);

const limits = {
    max_roll_correction: getNum(
        "tuning::rov::axis_clamp_roll",
        Number(legacyLimits.max_roll_correction ?? defaults.max_roll_correction)
    ),
    max_pitch_correction: getNum(
        "tuning::rov::axis_clamp_pitch",
        Number(legacyLimits.max_pitch_correction ?? defaults.max_pitch_correction)
    ),
    max_yaw_correction: getNum(
        "tuning::rov::axis_clamp_yaw",
        Number(legacyLimits.max_yaw_correction ?? defaults.max_yaw_correction)
    ),
    max_heave_correction: getNum(
        "tuning::rov::axis_clamp_heave",
        Number(legacyLimits.max_heave_correction ?? defaults.max_heave_correction)
    )
};

// ───────────────────────────────────────────────────────────
// APPLY CLAMP
// ───────────────────────────────────────────────────────────
//
// MANUAL:
//   full authority, no clamp
//
// STABLE / MAG / anything else:
//   clamp control outputs to configured limits
//

if (mode === "MANUAL") {
    msg.control = Object.assign({}, c);
} else {
    msg.control = Object.assign({}, c, {
        roll_thrust: clampAxis(c.roll_thrust, limits.max_roll_correction),
        pitch_thrust: clampAxis(c.pitch_thrust, limits.max_pitch_correction),
        yaw_thrust: clampAxis(c.yaw_thrust, limits.max_yaw_correction),
        heave_thrust: clampAxis(c.heave_thrust, limits.max_heave_correction)
    });
}

// ───────────────────────────────────────────────────────────
// DEBUG SNAPSHOT
// ───────────────────────────────────────────────────────────
//
// This gives you a clean view of:
//   • current mode
//   • nav source
//   • sensor snapshot
//   • control before clamp
//   • control after clamp
//   • clamp values actually used
//

msg.rov_debug = {
    ts: Date.now(),
    fleet_id: msg.router?.fleet_id || "",
    vessel_id: msg.router?.vessel_id || "rov-unknown",
    nav_source: flow.get(`nav_source::${msg.router?.vessel_id || ""}`) || "real",
    mode,
    sensors: {
        heading: msg.payload?.heading,
        pitch: msg.payload?.pitch,
        roll: msg.payload?.roll,
        depth: msg.payload?.depth,
        roll_rate: msg.payload?.roll_rate,
        pitch_rate: msg.payload?.pitch_rate,
        yaw_rate: msg.payload?.yaw_rate
    },
    control_in: c,
    control_out: msg.control,
    limits_applied: mode === "MANUAL" ? null : limits
};

// Output 1: normal message to next node
// Output 2: deep-copied debug branch
const dbg = JSON.parse(JSON.stringify(msg));
return [msg, dbg];

// ═══════════════════════════════════════════════════════════
// Cache Simulator Orientation (HA → Node-RED)
// ═══════════════════════════════════════════════════════════
//
// Purpose
// -------
// Maintain the latest simulator orientation values coming
// from Home Assistant helpers in Node-RED flow context.
//
// This node does NOT publish anything. It only updates the
// cached orientation object so other nodes can build and
// publish SignalK messages at a fixed rate.
//
// Inputs
// ------
// Messages arrive from HA `server-state-changed` nodes.
//
// msg.topic indicates which value changed:
//
//   roll_deg
//   pitch_deg
//   heading_deg
//   roll_rate_dps
//   pitch_rate_dps
//   yaw_rate_dps
//
// msg.payload contains the numeric value from the helper.
//
// Storage
// -------
// Data is stored in flow context:
//
//   flow.sim_rov_orientation
//
// Structure:
//
// {
//   roll_deg,
//   pitch_deg,
//   heading_deg,
//   roll_rate_dps,
//   pitch_rate_dps,
//   yaw_rate_dps
// }
//
// Behaviour
// ---------
// • Updates only the field indicated by msg.topic
// • Keeps previously stored values intact
// • Ensures all values remain available even if only one
//   helper changes.
//
// Downstream Use
// --------------
// The node `Build Signal K orientation msgs` reads this
// cached object and converts it to:
//
//   navigation/attitude
//   navigation/headingTrue
//   navigation/rateOfTurn
//
// published at a fixed rate (~5 Hz).
//
// ═══════════════════════════════════════════════════════════


const key = 'sim_rov_orientation';
const s = flow.get(key) || {
  roll_deg: 0,
  pitch_deg: 0,
  heading_deg: 0,
  roll_rate_dps: 0,
  pitch_rate_dps: 0,
  yaw_rate_dps: 0
};

const topic = String(msg.topic || '');
const val = Number(msg.payload);
if (!Number.isFinite(val)) return null;

s[topic] = val;
flow.set(key, s);
return null;

// ═══════════════════════════════════════════════════════════
// Build Signal K orientation msgs (NEW STANDARD)
// ═══════════════════════════════════════════════════════════
//
// Publishes:
//   navigation/attitude            {pitch, roll, yaw}   radians
//   navigation/headingTrue         {value}              radians
//   navigation/rateOfTurn          {value}              rad/s
//
// Source helpers are in degrees / deg/s.
// Device path includes /devices/simulator/
//
// ═══════════════════════════════════════════════════════════

const fleet_id = "NZAAT2510";
const vessel_id = "rov-02";
const device_id = "simulator";
const key = "sim_rov_orientation";
const s = flow.get(key) || {};

const deg2rad = Math.PI / 180.0;

const pitch_rad = (Number(s.pitch_deg) || 0) * deg2rad;
const roll_rad = (Number(s.roll_deg) || 0) * deg2rad;

// wrap heading into 0..360 before converting
let heading_deg = Number(s.heading_deg) || 0;
heading_deg = ((heading_deg % 360) + 360) % 360;
const yaw_rad = heading_deg * deg2rad;

// standard uses yaw rate only for rateOfTurn
const rot_rad_s = (Number(s.yaw_rate_dps) || 0) * deg2rad;
const roll_rate_rad_s = (Number(s.roll_rate_dps) || 0) * deg2rad;
const pitch_rate_rad_s = (Number(s.pitch_rate_dps) || 0) * deg2rad;

const base = `fleet/${fleet_id}/vessels/${vessel_id}/devices/${device_id}/navigation`;

return [[
    {
        topic: `${base}/attitude`,
        payload: JSON.stringify({
            pitch: Number(pitch_rad.toFixed(4)),
            roll: Number(roll_rad.toFixed(4)),
            yaw: Number(yaw_rad.toFixed(4))
        })
    },
    {
        topic: `${base}/headingTrue`,
        payload: JSON.stringify({
            value: Number(yaw_rad.toFixed(4))
        })
    },
    {
        topic: `${base}/rateOfTurn`,
        payload: JSON.stringify({
            value: Number(rot_rad_s.toFixed(4))
        })
    }
]];

const fleet_id = "NZAAT2510";
const vessel_id = "rov-02";
const device_id = "simulator";

const depth = Number(msg.payload);
if (!Number.isFinite(depth)) return null;

return {
    topic: `fleet/${fleet_id}/vessels/${vessel_id}/devices/${device_id}/navigation/depthBelowTransducer`,
    payload: JSON.stringify({
        value: Number(depth.toFixed(3))
    })
};

const parts = (msg.topic || "").split("/");
if (parts.length < 6) return null;

const fleet_id = parts[1];
const vessel_id = parts[3];

let src = msg.payload;
if (typeof src === "object" && src) {
    src = src.source ?? src.value ?? src.payload;
}

src = String(src || "").trim().toLowerCase();
if (src === "simulator") src = "sim";
if (src !== "real" && src !== "sim") return null;

flow.set(`nav_source::${vessel_id}`, src);
node.status({ fill: src === "sim" ? "yellow" : "green", shape: "dot", text: `${vessel_id}: ${src}` });

return {
    topic: `fleet/${fleet_id}/vessels/${vessel_id}/control/nav_source`,
    payload: {
        source: src,
        ts: Date.now()
    }
};

const parts = (msg.topic || "").split("/");
if (parts.length < 7) return null;

const fleet_id = parts[1];
const vessel_id = parts[3];
const device_id = String(parts[5] || "").trim().toLowerCase();
const topicKey = parts[parts.length - 1];

const source = device_id === "simulator" ? "sim" : "real";
const activeSource = flow.get(`nav_source::${vessel_id}`) || "real";
const now = Date.now();

let p = msg.payload;

// handle JSON string payloads
if (typeof p === "string") {
    try {
        p = JSON.parse(p);
    } catch (e) {
        node.warn(`Bad JSON payload on ${msg.topic}: ${msg.payload}`);
        return null;
    }
}

if (typeof p !== "object" || p === null) {
    node.warn(`Payload not object on ${msg.topic}`);
    return null;
}

function storeMetric(metric, value) {
    if (!Number.isFinite(value)) return;
    flow.set(`navsrc::${vessel_id}::${source}::${metric}`, value);
    flow.set(`navsrc_ts::${vessel_id}::${source}::${metric}`, now);
    flow.set(`nav_fleet::${vessel_id}`, fleet_id);

    if (source === activeSource) {
        flow.set(`nav::${vessel_id}::${metric}`, value);
        flow.set(`nav::${vessel_id}::source`, source);
        flow.set(`nav::${vessel_id}::updated`, now);
    }
}

if (topicKey === "attitude") {
    storeMetric("pitch", Number(p.pitch));
    storeMetric("roll", Number(p.roll));
    storeMetric("heading", Number(p.yaw));

} else if (topicKey === "headingTrue") {
    storeMetric("heading", Number(p.value));

} else if (topicKey === "rateOfTurn") {
    storeMetric("yaw_rate", Number(p.value));

} else if (topicKey === "depthBelowTransducer") {
    storeMetric("depth", Number(p.value));

} else if (topicKey === "position") {
    storeMetric("lat", Number(p.latitude));
    storeMetric("lon", Number(p.longitude));
    storeMetric("alt", Number(p.altitude));

} else if (topicKey === "speedOverGround") {
    storeMetric("sog", Number(p.value));
    storeMetric("speed", Number(p.value));

} else if (topicKey === "courseOverGroundTrue") {
    storeMetric("cog", Number(p.value));

} else if (topicKey === "gnss") {
    storeMetric("sats", Number(p.count));
    storeMetric("hdop", Number(p.hdop ?? p.horizontalDilution ?? p.horizontal_dilution));

} else {
    return null;
}

return null;

const router = msg.router || {};
if (!router.fleet_id || !router.vessel_id) return null;
if (!msg.rov_debug) return null;

return {
    topic: `fleet/${router.fleet_id}/vessels/${router.vessel_id}/control/debug/stable`,
    payload: msg.rov_debug
};

// HA -> Flow tuning sync
// Takes HA helper changes and writes into flow context:
// tuning::rov::*
// tuning::tender::*

const entity = String(msg.entity_id || msg.topic || "").trim();
const raw = msg.payload;

// reject HA junk states early
if (raw === null) return null;

const sraw = String(raw).toLowerCase();
if (sraw === "unknown" || sraw === "unavailable" || sraw === "nan") return null;

// sanity check
if (!entity) return null;

// split: input_number.rov_roll_p → [input_number, rov_roll_p]
const parts = entity.split('.');
if (parts.length !== 2) return null;

const domain = parts[0];   // input_number / input_boolean
const name = parts[1];     // rov_* / tender_*

// only accept our tuning helpers
if (domain !== 'input_number' && domain !== 'input_boolean') return null;
if (!(name.startsWith('rov_') || name.startsWith('tender_'))) return null;

// convert value
let value;

if (domain === 'input_boolean') {
    // HA booleans come as "on"/"off"
    const s = String(raw).toLowerCase();
    value = (raw === true || s === 'on' || s === 'true' || raw === 1 || raw === '1');
} else {
    // numbers
    value = Number(raw);
    if (!Number.isFinite(value)) return null;
}

// build flow key
// rov_roll_p → tuning::rov::roll_p
// tender_dp_p → tuning::tender::dp_p
let key = null;

if (name.startsWith('rov_')) {
    key = `tuning::rov::${name.substring(4)}`;
} 
else if (name.startsWith('tender_')) {
    key = `tuning::tender::${name.substring(7)}`;
}

if (!key) return null;

// write to flow context
flow.set(key, value);

// optional debug output
msg.topic = key;
msg.payload = value;

return msg;

// Force nav source to REAL on boot

const vessels = ["rov-02", "tender-01"];
const metrics = ["roll", "pitch", "heading", "yaw_rate", "roll_rate", "pitch_rate", "depth", "lat", "lon", "sog", "speed", "sats", "cog"];

for (const v of vessels) {
    flow.set(`nav_source::${v}`, "real");
    for (const m of metrics) {
        flow.set(`nav::${v}::${m}`, 0);
    }
}

node.status({ fill: "green", shape: "dot", text: "nav source = real, cache cleared (boot)" });

// Force nav source to REAL on boot

const vessels = ["rov-02", "tender-01"]; // add more if needed

for (const v of vessels) {
    flow.set(`nav_source::${v}`, "sim");
}

node.status({ fill: "yellow", shape: "dot", text: "nav source = SIMULATOR" });

return null;

// Decode base64-encoded MAVLink data
msg.payload = Buffer.from(msg.payload, 'base64');
return msg;

const heading = Math.round(Number(msg.payload));
msg.headers = { "Content-Type": "application/json" };
msg.payload = { heading };
msg.url = "http://172.16.10.10:8089/mavlink/vehicles/1/components/1/messages/VFR_HUD";
return msg;

// m2r SSE sends lines like: { path: "mavlink/...", value: ... }
// ensure a flat object; Cockpit expects WS payloads, so stringify.
const ev = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
msg.payload = JSON.stringify({ path: ev.path, value: ev.value });
return msg;

// Store gyro rates for ATTITUDE message
const parts = (msg.topic || '').split('/');
if (parts.length < 5) return null;

const vessel_id = parts[3];
const rates = msg.payload || {};

// Store in flow context (rad/s)
flow.set(`mav::${vessel_id}::pitch_rate`, rates.pitch || 0);
flow.set(`mav::${vessel_id}::roll_rate`, rates.roll || 0);
flow.set(`mav::${vessel_id}::yaw_rate`, rates.yaw || 0);

return null; // Don't pass through

// Build MAVLink ATTITUDE message (#30)
const parts = (msg.topic || '').split('/');
if (parts.length < 5) return null;

const vessel_id = parts[3];
const att = msg.payload || {};

// Get gyro rates from flow context
const rollspeed = flow.get(`mav::${vessel_id}::roll_rate`) || 0;
const pitchspeed = flow.get(`mav::${vessel_id}::pitch_rate`) || 0;
const yawspeed = flow.get(`mav::${vessel_id}::yaw_rate`) || 0;

// Build MAVLink payload
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    roll: att.roll || 0,           // radians
    pitch: att.pitch || 0,         // radians
    yaw: att.yaw || 0,             // radians
    rollspeed: rollspeed,          // rad/s
    pitchspeed: pitchspeed,        // rad/s
    yawspeed: yawspeed             // rad/s
};

msg.url = "http://172.16.10.10:8089/mavlink/vehicles/1/components/1/messages/ATTITUDE";
return msg;

// Build MAVLink VFR_HUD message (#74)
const parts = (msg.topic || '').split('/');
if (parts.length < 5) return null;

const vessel_id = parts[3];
const depth = msg.payload.value || 0;

// Get heading from flow context
const heading_rad = flow.get(`mav::${vessel_id}::heading`) || 0;
const heading_deg = Math.round((heading_rad * 180 / Math.PI) % 360);

// Store depth for other messages
flow.set(`mav::${vessel_id}::depth`, depth);

// Build MAVLink payload
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    heading: heading_deg,          // degrees
    alt: depth,                    // meters (using depth as altitude)
    groundspeed: 0,                // m/s (no speed sensor)
    airspeed: 0,                   // m/s
    climb: 0,                      // m/s
    throttle: 0                    // %
};

msg.url = "http://172.16.10.10:8089/mavlink/vehicles/1/components/1/messages/VFR_HUD";
return msg;

// Build MAVLink GLOBAL_POSITION_INT message (#33)
const parts = (msg.topic || '').split('/');
if (parts.length < 5) return null;

const vessel_id = parts[3];
const pos = msg.payload || {};

// Get depth from flow context
const depth = flow.get(`mav::${vessel_id}::depth`) || 0;

// MAVLink expects lat/lon in degE7 (degrees * 1e7)
const lat = Math.round((pos.latitude || 0) * 1e7);
const lon = Math.round((pos.longitude || 0) * 1e7);
const alt = Math.round(depth * 1000);  // mm

// Build MAVLink payload
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    lat: lat,                      // degE7
    lon: lon,                      // degE7
    alt: alt,                      // mm (MSL)
    relative_alt: alt,             // mm (relative to home)
    vx: 0,                         // cm/s
    vy: 0,                         // cm/s
    vz: 0,                         // cm/s
    hdg: 0                         // cdeg (0-360)
};

msg.url = "http://172.16.10.10:8089/mavlink/vehicles/1/components/1/messages/GLOBAL_POSITION_INT";
return msg;

// Build MAVLink HEARTBEAT message (#0)
// Required to keep connection alive

msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    type: 12,              // MAV_TYPE_SUBMARINE
    autopilot: 8,          // MAV_AUTOPILOT_INVALID (custom)
    base_mode: 81,         // ARMED | CUSTOM_MODE_ENABLED
    custom_mode: 0,
    system_status: 4,      // MAV_STATE_ACTIVE
    mavlink_version: 3
};

msg.url = "http://172.16.10.10:8089/mavlink/vehicles/1/components/1/messages/HEARTBEAT";
return msg;

// Normalize SSE events for WebSocket clients
const ev = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
msg.payload = JSON.stringify({ path: ev.path, value: ev.value });
return msg;

// Extract and store heading for VFR_HUD
const parts = (msg.topic || '').split('/');
if (parts.length < 5) return null;

const vessel_id = parts[3];
const att = msg.payload || {};

// Store yaw as heading
flow.set(`mav::${vessel_id}::heading`, att.yaw || 0);

return null;

const manifest = msg.payload;
const devices = manifest.devices;

const tableData = [];
for (const [mac, device] of Object.entries(devices)) {
    tableData.push({
        mac: mac,
        name: device.name,
        fullname: device.fullname || device.name,
        vessel_id: device.vessel_id,
        role: Array.isArray(device.role) ? device.role.join(', ') : device.role,
        ha_device_name: device.ha ? device.ha.device_name : 'N/A',
        manufacturer: device.ha ? device.ha.manufacturer : 'N/A',
        model: device.ha ? device.ha.model : 'N/A',
        sw_version: device.ha ? device.ha.sw_version : 'N/A'
    });
}

msg.payload = tableData;
return msg;

if (msg.payload && msg.payload.mac) {
    flow.set('selectedMac', msg.payload.mac);
}
return null;

const manifest = flow.get('manifest') || global.get('fleet_manifest');
const macRaw = flow.get('selectedMac');

if (!manifest || !manifest.devices) {
    node.warn('Manifest not loaded');
    return null;
}
if (!macRaw) {
    node.warn('No device selected');
    return null;
}

const mac = String(macRaw).toUpperCase().replace(/[^0-9A-F]/g, '');
const device = manifest.devices[mac];
if (!device) {
    node.warn(`Selected device not found: ${mac}`);
    return null;
}

msg.payload = {
    is_edit: true,
    mac: mac,
    vessel_id: device.vessel_id || '',
    name: device.name || '',
    fullname: device.fullname || '',
    role: Array.isArray(device.role) ? device.role.join(',') : (device.role || ''),
    craft_type: (device.craft_type ?? ''),
    craft_id: (device.craft_id ?? ''),
    udp_port: (device.udp_port ?? 14560),
    ha_device_name: device.ha?.device_name || '',
    ha_manufacturer: device.ha?.manufacturer || 'OpenSubsea',
    ha_model: device.ha?.model || '',
    ha_sw_version: device.ha?.sw_version || ''
};
return msg;

const mac = flow.get('selectedMac');

if (!mac) {
    node.warn('No device selected');
    return null;
}

msg.payload = { action: 'delete', mac: mac };
return msg;

const manifest = flow.get('manifest') || global.get('fleet_manifest');
if (!manifest || !manifest.devices) {
    node.error('Manifest not loaded');
    return null;
}

const d = msg.payload?.device || {};
const clean = (s) => String(s ?? '').trim();
const mac = clean(d.mac).toUpperCase().replace(/[^0-9A-F]/g, '');

if (!/^[0-9A-F]{12}$/.test(mac)) {
    node.error(`Invalid MAC '${d.mac}' (must be 12 hex chars)`);
    return null;
}

const vessel_id = clean(d.vessel_id);
const name = clean(d.name);
const fullname = clean(d.fullname) || name;
if (!vessel_id || !name) {
    node.error('vessel_id and name are required');
    return null;
}

const rolesRaw = clean(d.role);
if (!rolesRaw) {
    node.error('role is required');
    return null;
}
const roles = rolesRaw.split(',').map(r => r.trim()).filter(Boolean);
const allowedRoles = new Set(['bridge', 'driver', 'sensor']);
if (roles.some(r => !allowedRoles.has(r))) {
    node.error(`Invalid role(s): ${roles.join(',')}`);
    return null;
}

const hasCraftType = clean(d.craft_type) !== '';
const hasCraftId = clean(d.craft_id) !== '';
let craft_type, craft_id, udp_port;

if (hasCraftType) {
    craft_type = Number(d.craft_type);
    if (!Number.isInteger(craft_type) || craft_type < 0 || craft_type > 255) {
        node.error('craft_type must be integer 0..255');
        return null;
    }
}
if (hasCraftId) {
    craft_id = Number(d.craft_id);
    if (!Number.isInteger(craft_id) || craft_id < 0 || craft_id > 255) {
        node.error('craft_id must be integer 0..255');
        return null;
    }
}

udp_port = (clean(d.udp_port) === '') ? 14560 : Number(d.udp_port);
if (!Number.isInteger(udp_port) || udp_port < 1 || udp_port > 65535) {
    node.error('udp_port must be integer 1..65535');
    return null;
}

const device = {
    vessel_id,
    name,
    fullname,
    role: roles.length === 1 ? roles[0] : roles
};

if (hasCraftType) device.craft_type = craft_type;
if (hasCraftId) device.craft_id = craft_id;
device.udp_port = udp_port;

const haName = clean(d.ha_device_name);
const haModel = clean(d.ha_model);
const haVer = clean(d.ha_sw_version);
if (haName || haModel || haVer) {
    device.ha = {
        device_name: haName || name,
        manufacturer: clean(d.ha_manufacturer) || 'OpenSubsea',
        model: haModel || '',
        sw_version: haVer || ''
    };
}

manifest.devices[mac] = device;
flow.set('manifest', manifest);
global.set('fleet_manifest', manifest);

msg.payload = JSON.stringify(manifest, null, 2);
return msg;

const manifest = flow.get('manifest');
const mac = msg.payload.mac;

if (manifest.devices[mac]) {
    delete manifest.devices[mac];
    flow.set('manifest', manifest);
    msg.payload = JSON.stringify(manifest, null, 2);
    return msg;
}
return null;
